window.SARE_EVENT_CONTEXT = {
"آغاز به کار نخستین فرستنده عمومی رادیویی در ایران به نام «رادیو تهران»": "رادیو تهران در سال ۱۳۱۹ خورشیدی، در چارچوب سیاست‌های نوسازی رضاشاه، به‌عنوان نخستین رسانه‌ی صوتی سراسری ایران آغاز به کار کرد. این ایستگاه اخبار، موسیقی و برنامه‌های فرهنگی را برای نخستین‌بار به‌طور هم‌زمان به سراسر کشور می‌رساند و زمینه‌ساز گسترش رسانه‌ی رادیویی در دهه‌های بعد شد.",
"آغاز حمله مغول به ایران در پاییز 598 خورشیدی": "یورش مغولان به رهبری چنگیزخان از سال ۵۹۸ خورشیدی (۱۲۱۹ میلادی) آغاز شد، پس از آنکه فرمانده خوارزمشاهیِ شهر اُترار بازرگانان و سفیران مغول را کشت. سپاه مغول شهرهای بزرگ خراسان و ماوراءالنهر از جمله بخارا، سمرقند، نیشابور و مرو را ویران و جمعیت آن‌ها را قتل‌عام کرد. این حمله به فروپاشی امپراتوری خوارزمشاهیان انجامید و یکی از ویرانگرترین و پرتلفات‌ترین رویدادهای تاریخ ایران به‌شمار می‌رود.",
"آغاز کار نخستین فرستنده تلویزیون دولتی ایران، به نام «شبکه ملی»": "تلویزیون دولتی ایران با نام «شبکه ملی» در سال ۱۳۴۵ خورشیدی راه‌اندازی شد، حدود یک دهه پس از تأسیس نخستین تلویزیون خصوصی کشور توسط حبیب ثابت در سال ۱۳۳۷. این شبکه بعدها با تلویزیون‌های دیگر ادغام شد و سازمان رادیو تلویزیون ملی ایران (NIRT) را شکل داد که تا پیش از انقلاب اسلامی اصلی‌ترین نهاد پخش تصویری کشور بود.",
"اشغال ایران توسط متفقین": "در شهریور ۱۳۲۰ (اوت-سپتامبر ۱۹۴۱)، نیروهای شوروی از شمال و بریتانیا از جنوب، با وجود اعلام بی‌طرفی رسمی ایران در جنگ جهانی دوم، وارد خاک کشور شدند. دلیل اصلی این تهاجم، نگرانی متفقین از گرایش‌های رضاشاه به آلمان نازی و نیاز آن‌ها به «راهروی ایران» برای رساندن تسلیحات به شوروی بود. این اشغال به کناره‌گیری اجباری رضاشاه از سلطنت و روی‌کار‌آمدن پسرش محمدرضا پهلوی انجامید و ایران تا پایان جنگ زیر نفوذ نظامی متفقین باقی ماند.",
"اعدام بابک خرمدین به دست معتصم، خلیفه عباسی در سامرا": "بابک خرمدین، رهبر جنبش خُرّمیان، بیش از دو دهه (از حدود ۲۰۱ تا ۲۲۲ هجری قمری) از دژ بذّ در آذربایجان علیه سلطه‌ی خلافت عباسی مقاومت مسلحانه کرد. سرانجام او با فریب به خیانت افشین، سردار ایرانی‌تبار خلیفه، اسیر شد و به سامرا نزد معتصم خلیفه فرستاده شد. اعدام دردناک او در سال ۲۲۳ هجری قمری رخ داد و بابک از آن پس به نمادی از مقاومت ایرانیان در برابر سلطه‌ی خارجی بدل شده است.",
"اعدام میهن‌پرستان آذری در تبریز توسط قوای اشغالگر روس [1290 خورشیدی]": "در جریان بحران پایانی جنبش مشروطه (۱۲۹۰ خورشیدی/۱۹۱۱ میلادی)، روسیه‌ی تزاری با بهانه‌ی حمایت از منافعش، نیروی نظامی به آذربایجان و تبریز اعزام کرد. پس از سرکوب مقاومت مردمی، شماری از فعالان و رهبران ملی‌گرای مشروطه‌خواه در تبریز به دستور فرماندهان روس بدون محاکمه‌ی عادلانه اعدام شدند. این رویداد یکی از تلخ‌ترین نمونه‌های دخالت مستقیم قدرت‌های خارجی در سرکوب جنبش مشروطه‌ی ایران است.",
"امضای معاهده تقسیم ایران بین روسیه و انگلیس": "قرارداد ۱۹۰۷ میان روسیه‌ی تزاری و بریتانیا، بدون مشورت با دولت ایران، کشور را به سه حوزه تقسیم کرد: منطقه‌ی نفوذ روسیه در شمال، منطقه‌ی نفوذ بریتانیا در جنوب‌شرق (نزدیک هند و خلیج فارس)، و یک منطقه‌ی بی‌طرف در میانه. هدف اصلی این توافق، پایان‌دادن به رقابت دو امپراتوری بر سر ایران در چارچوب «بازی بزرگ» بود، نه منافع ایران. این معاهده به‌عنوان یکی از آشکارترین نمونه‌های نقض حاکمیت ملی ایران در دوران قاجار همواره مورد انتقاد تاریخ‌نگاران بوده است.",
"انتشار نخستین روزنامه در ایران به نام «کاغذ اخبار» توسط «میرزا صالح شیرازی»": "کاغذ اخبار در سال ۱۲۵۳ هجری قمری (۱۸۳۷ میلادی)، در دوران محمدشاه قاجار، به همت میرزا صالح شیرازی -یکی از نخستین دانشجویان اعزامی ایران به اروپا- منتشر شد. این نشریه به‌صورت چاپ سنگی و با محتوایی عمدتاً درباره‌ی اخبار دربار و دولت تهیه می‌شد و آغازگر سنت مطبوعات نوین در ایران به‌شمار می‌رود.",
"برگزاری انتخابات دوره نخست مجلس شورای ملی": "پس از صدور فرمان مشروطیت توسط مظفرالدین‌شاه در مرداد ۱۲۸۵، نخستین دوره‌ی انتخابات مجلس شورای ملی برگزار و مجلس در مهرماه همان سال گشایش یافت. این رویداد، گذار نمادین ایران از سلطنت مطلقه به حکومت مشروطه و پارلمانی را رقم زد و سرآغاز تجربه‌ی قانون‌گذاریِ نوین در کشور بود.",
"برگزاری اولین کنکور در ایران": "پیش از استقرار نظام کنکور سراسری، هر دانشگاه ایرانی به‌طور جداگانه و با معیارهای خود دانشجو می‌پذیرفت که به ناهماهنگی و نابرابری در گزینش می‌انجامید. نخستین آزمون سراسری ورودی دانشگاه‌ها در دهه‌ی ۱۳۴۰ خورشیدی برگزار شد و ساختار یکسانی برای پذیرش دانشجو در سراسر کشور پدید آورد که بنیاد نظام کنکور امروز ایران است.",
"بزرگداشت ابونصر فارابی": "ابونصر فارابی (حدود ۲۵۹-۳۳۹ هجری قمری)، در فاراب ترکستان زاده شد و در بغداد تحصیل و تدریس کرد. او را به سبب گستردگی و ژرفای آثارش در منطق و فلسفه، «معلم ثانی» پس از ارسطو لقب داده‌اند. فارابی در کتاب «آرای اهل مدینه فاضله» به فلسفه‌ی سیاسی و آرمان‌شهر پرداخت و در «الموسیقی الکبیر» یکی از مهم‌ترین رساله‌های نظری موسیقی جهان اسلام را نوشت؛ اندیشه‌های او تأثیر عمیقی بر ابن سینا و فیلسوفان پس از خود گذاشت.",
"بزرگداشت حکیم هادی سبزواری": "ملاهادی سبزواری (۱۱۷۶-۱۲۸۹ هجری قمری) از برجسته‌ترین فیلسوفان مکتب حکمت متعالیه در دوران قاجار بود که میراث فلسفی ملاصدرا را در سبزوار احیا و تدریس کرد. مهم‌ترین اثر او، «شرح منظومه»، سال‌ها متن درسی اصلی فلسفه در حوزه‌های علمیه‌ی ایران بوده و همچنان مرجع آموزش حکمت اسلامی است.",
"بزرگداشت خواجوی کرمانی": "کمال‌الدین ابوالعطا خواجوی کرمانی (۶۸۹-۷۵۳ هجری قمری) شاعر سده‌ی هشتم هجری بود که بخش بزرگی از عمر خود را در شیراز گذراند. سبک غزل‌سرایی او را از پیشگامان تأثیرگذار بر شعر حافظ می‌دانند، به‌گونه‌ای که شباهت‌های آشکاری میان اشعار این دو دیده می‌شود. آرامگاه او در شیراز هنوز مقصد علاقه‌مندان ادب فارسی است.",
"بزرگداشت رودکی": "ابوعبدالله جعفر رودکی (حدود ۲۴۴-۳۲۹ هجری قمری) را «پدر شعر فارسی دری» می‌نامند، چرا که نخستین دیوان شعر قابل‌توجه به زبان فارسی نو به او منسوب است. او شاعر و نوازنده‌ی چیره‌دست دربار سامانیان در بخارا بود و بنا بر روایتی معروف، با سرودن قصیده‌ای درباره‌ی بوی جوی مولیان، امیر سامانی را از سفری طولانی به بازگشت به بخارا ترغیب کرد. بیشتر اشعار او در طول قرون از میان رفته و تنها بخش اندکی باقی مانده است.",
"بزرگداشت سید جمال‌الدین اسدآبادی": "سید جمال‌الدین اسدآبادی، معروف به افغانی (۱۲۱۷-۱۲۷۶ خورشیدی)، از پیشگامان اندیشه‌ی اصلاح‌طلبی و اتحاد اسلامی در سده‌ی نوزدهم بود که در مصر، هند، عثمانی و ایران به فعالیت فکری و سیاسی پرداخت. او مردم را به بیداری در برابر استعمار غربی و اصلاحات درونی جهان اسلام فرامی‌خواند و نقشی مهم در تحریک افکار عمومی ایران در جریان جنبش تحریم تنباکو داشت. سرانجام در استانبول درگذشت؛ خاستگاه دقیق او (ایرانی شیعه یا افغان سنی) هنوز میان پژوهشگران محل بحث است.",
"بزرگداشت شیخ صفی‌الدین اردبیلی": "شیخ صفی‌الدین اردبیلی (۶۵۰-۷۳۵ هجری قمری) عارف و بنیان‌گذار طریقت صفویه در اردبیل بود. اهمیت تاریخی او فراتر از عرفان است: نسل‌های بعدی خاندانش، طریقت صوفیانه‌ی خانوادگی را به‌تدریج به قدرت سیاسی-نظامی بدل کردند و سرانجام نتیجه‌اش، شاه اسماعیل یکم، در سال ۹۰۷ هجری قمری سلسله‌ی صفوی را بنیان نهاد که ایران را دوباره زیر یک حکومت واحد و مذهب رسمی تشیع متحد کرد.",
"بزرگداشت صفی‌الدین اُرمَوی و روز موسیقی ایرانی": "صفی‌الدین ارموی (حدود ۶۱۳-۶۹۳ هجری قمری)، اهل ارومیه، در دربار بغداد -حتی پس از سقوط این شهر به دست مغولان- به‌عنوان موسیقی‌دان و نظریه‌پرداز فعالیت می‌کرد. او در کتاب «الادوار» نظامی علمی و منسجم برای دستگاه‌ها و مقام‌های موسیقی ایرانی-عربی تدوین کرد که بنیادی برای نظریه‌ی موسیقی کلاسیک منطقه در سده‌های بعد شد.",
"بزرگداشت نظامی گنجوی": "نظامی گنجوی (۵۳۵-۶۰۵ هجری قمری) در گنجه (در قفقاز، آذربایجان امروزی) زاده شد و «خمسه» یا «پنج گنج» را سرود: مخزن‌الاسرار، خسرو و شیرین، لیلی و مجنون، هفت پیکر، و اسکندرنامه. این منظومه‌های عاشقانه و حکمی چنان تأثیرگذار بودند که شاعران بی‌شماری در زبان‌های فارسی، ترکی و اردو تلاش کردند بر وزن و مضمون آن‌ها «نظیره» بسرایند.",
"تأسیس باشگاه فوتبال استقلال (تاج)": "این باشگاه در سال ۱۳۲۴ خورشیدی با نام «دوچرخه‌سواران» توسط جهانبخش رسخ‌چای و همکارانش بنیان نهاده شد و پس از مدتی، با حمایت دربار پهلوی، به «تاج» تغییر نام یافت. پس از انقلاب اسلامی ۱۳۵۷، نام باشگاه به «استقلال» تبدیل شد. امروز استقلال یکی از دو باشگاه پرافتخار و پرطرفدار فوتبال ایران و رقیب سنتی پرسپولیس است.",
"تأسیس حزب توده ایران": "حزب توده‌ی ایران در مهر ۱۳۲۰، بلافاصله پس از سقوط رضاشاه (که فعالیت احزاب چپ را ممنوع کرده بود)، با گرایش مارکسیستی-لنینیستی تأسیس شد. این حزب در دهه‌های ۱۳۲۰ و ۱۳۳۰ یکی از بزرگ‌ترین و سازمان‌یافته‌ترین نیروهای سیاسی ایران بود و در مناظرات مربوط به ملی‌شدن صنعت نفت نقش داشت. پس از کودتای ۲۸ مرداد ۱۳۳۲ به‌شدت سرکوب شد، اما همچنان یکی از تأثیرگذارترین جریان‌های تاریخ سیاسی معاصر ایران به‌شمار می‌رود.",
"جشن آب پاشونک، جشن آغاز تابستان": "آب‌پاشونک آیینی محلی برای خوشامدگویی به آغاز فصل تابستان است که در آن مردم با پاشیدن نمادین آب بر یکدیگر، فرارسیدن گرما و برکت آب را جشن می‌گیرند. ریشه‌ی این آیین را می‌توان به احترام کهن ایرانیان باستان به عنصر آب و ایزدبانوی آناهیتا پیوند داد.",
"جشن سده، گرامیداشتِ کشف آتش به دستِ هوشنگ شاه": "جشن سده در دهم بهمن‌ماه، پنجاه شب مانده به نوروز، برگزار می‌شود و ریشه در افسانه‌ای از شاهنامه دارد: هوشنگ‌شاه پیشدادی هنگام پرتاب سنگی به‌سوی ماری، ناخواسته با برخورد آن سنگ به سنگی دیگر جرقه و آتش پدید آورد. این جشن با افروختن آتش‌های بزرگ گرامی داشته می‌شود و امروز به‌ویژه در میان جامعه‌ی زرتشتیان یزد و کرمان با شکوه برگزار می‌شود.",
"جشن سپندارمذگان و روز عشق": "سپندارمذگان جشنی باستانی به‌نام اسپندارمذ، ایزدبانوی زمین، باروری و عشق در آیین زرتشتی است. در سال‌های اخیر این روز به‌عنوان یک جایگزین فرهنگی-ایرانی برای روز ولنتاین غربی معرفی و «روز عشق ایرانی» نامیده شده، هرچند این بازخوانی، برداشتی نو از یک سنت کهن‌تر است.",
"جشن سیزده به در": "در روز سیزدهم فروردین، ایرانیان طبق سنتی دیرینه از خانه بیرون می‌روند و روز را در دامان طبیعت می‌گذرانند؛ باوری عامیانه می‌گوید این کار، شگون نحسی عدد سیزده را از خانه دور می‌کند. رسم است که سبزه‌ی سفره‌ی هفت‌سین را نیز در همین روز به آب روان می‌سپارند، کرداری که پایانی نمادین بر جشن‌های نوروزی می‌گذارد.",
"جشن شب یلدا، شب چلّه": "شب یلدا، طولانی‌ترین شب سال و شب انقلاب زمستانی، از دیرباز نمادِ زایش خورشید و ایزد مهر پس از تاریک‌ترین شب سال بوده است. خانواده‌ها این شب را گرد هم می‌آیند، هندوانه و انار و آجیل می‌خورند و با گشودن دیوان حافظ به فال‌گیری (فال حافظ) تا سپیده‌دم بیدار می‌مانند.",
"جشن میانه بهار/جشن بهاربد": "جشن میانه‌ی بهار، جشنی باستانی در تقویم عامیانه‌ی ایرانی است که نیمه‌ی راه فصل بهار را نشانه می‌گذارد و یادآور جشن‌های فصلی متعددی است که ایرانیان باستان برای پیوند با چرخه‌ی طبیعت برگزار می‌کردند.",
"جشن میانه زمستان": "جشن میانه‌ی زمستان، همتای زمستانیِ جشن‌های فصلی ایران باستان، نقطه‌ی میانی این فصل را در تقویم عامیانه گرامی می‌دارد.",
"جشن میانه پاییز": "جشن میانه‌ی پاییز، در تقویم عامیانه‌ی ایرانی، نیمه‌راهِ فصل پاییز را جشن می‌گیرد و از سلسله‌جشن‌های فصلی باستانی ایرانیان است.",
"جشن نوروز/جشن سال نو": "نوروز، هم‌زمان با اعتدال بهاری، کهن‌ترین و مهم‌ترین جشن ملی ایرانیان و اقوام همسایه است که ریشه در آیین‌های ایران باستان (از جمله دوران زرتشتی و پیش از آن) دارد. این جشن نه‌تنها در ایران، بلکه در افغانستان، آسیای میانه، قفقاز و مناطق کردنشین نیز با آداب مشابه برگزار می‌شود و یونسکو آن را به‌عنوان میراث ناملموس بشریت به ثبت رسانده است.",
"جشن چله تابستان": "چله‌ی تابستان، اوج گرمای فصل تابستان در تقویم عامیانه‌ی ایرانی، همتای «چله»ی مشهور زمستان است که در فرهنگ عامه به آن نیز توجه می‌شود.",
"جشن چهلم نوروز": "چهلمین روز پس از نوروز در برخی مناطق ایران، پایانی نمادین بر فصل گسترده‌ی جشن‌های آغاز سال نو دانسته می‌شود و با آیین‌های محلی خاصی همراه است.",
"حمله به مسجد گوهرشاد و کشتار مردم به دست رضاخان": "در تیر ۱۳۱۴، اعتراض به سیاست‌های نوسازی اجباری رضاشاه -به‌ویژه اجبار به پوشش لباس متحدالشکل و کلاه پهلوی- در مسجد گوهرشاد مشهد به تجمعی گسترده انجامید. نیروهای نظامی با خشونت این تجمع را سرکوب کردند و شمار قابل‌توجهی از مردم کشته یا زخمی شدند. این رویداد یکی از تلخ‌ترین و جنجالی‌ترین نمونه‌های برخورد قهرآمیز دولت با مخالفان سیاست‌های مدرن‌سازی در دوران رضاشاه است.",
"درگذشت ابن سینا فیلسوف، پزشک و دانشمند نامدار ایرانی": "ابوعلی سینا (۳۷۰-۴۲۸ هجری قمری)، در نزدیکی بخارا زاده شد و یکی از تأثیرگذارترین دانشمندان تاریخ بشر است. کتاب «قانون در طب» او سده‌ها -تا اوایل دوران مدرن- در دانشگاه‌های اروپا تدریس می‌شد و «کتاب شفا»ی او دانشنامه‌ای گسترده در فلسفه به‌شمار می‌رود. او در کنار فعالیت علمی، در دربار چند حاکم به‌عنوان پزشک و حتی وزیر خدمت کرد و سرانجام در همدان درگذشت؛ آرامگاه او در این شهر امروز از بناهای یادبود مهم ایران است.",
"درگذشت ابوالحسن صدیقی نقاش و مجسمه‌ساز برجستهٔ ایرانی": "ابوالحسن صدیقی (۱۲۷۵-۱۳۷۴ خورشیدی) از شاگردان کمال‌الملک بود و بسیاری از مجسمه‌های نمادین تهران، از جمله پیکره‌ی فردوسی، از آثار اوست. او یکی از پایه‌گذاران آموزش نوین مجسمه‌سازی در ایران محسوب می‌شود.",
"درگذشت اسماعیل ادیب خوانساری موسیقیدان ایرانی": "اسماعیل ادیب خوانساری (۱۲۸۰-۱۳۶۱ خورشیدی) آوازخوانی سرشناس بود که به تسلط کامل بر ردیف موسیقی سنتی ایران شهرت داشت. ضبط‌های صوتی برجای‌مانده از او امروز نیز از منابع آموزشی مهم برای آواز سنتی ایرانی به‌شمار می‌روند.",
"درگذشت اکبر رادی نمایشنامه نویس ایرانی": "اکبر رادی (۱۳۱۸-۱۳۸۶ خورشیدی) را یکی از بنیان‌گذاران نمایشنامه‌نویسی رئالیستی و اجتماعی ایران می‌دانند. آثار او، مانند «مرگ در پاییز» و «لبخند باشکوه آقای گیل»، عمدتاً به زندگی مردم عادی در شمال ایران می‌پردازند و از متون کلاسیک تئاتر معاصر فارسی محسوب می‌شوند.",
"درگذشت جبار باغچه‌بان بنیان‌گذار نخستین کودکستان و نخستین مدرسه ناشنوایان ایران، اولین مؤلف و ناشر کتاب کودک در ایران": "جبار باغچه‌بان (۱۲۶۴-۱۳۴۵ خورشیدی) پیشگام آموزش نوین کودکان در ایران بود. او نخستین کودکستان و نخستین مدرسه‌ی ویژه‌ی کودکان ناشنوا را در ایران بنیان نهاد و همچنین نخستین کسی بود که به‌طور منظم کتاب کودک تألیف و منتشر کرد. خدمات او بنیادی برای آموزش‌وپرورش نوین و آموزش کودکان با نیازهای ویژه در ایران به‌شمار می‌رود.",
"درگذشت جلال آل احمد روشنفکر دینی، نویسنده و مترجم ایرانی و همسر سیمین دانشور": "جلال آل‌احمد (۱۳۰۲-۱۳۴۸ خورشیدی) با کتاب تأثیرگذار «غرب‌زدگی» نگاهی انتقادی به پذیرش بی‌چون‌وچرای فرهنگ غربی در ایران ارائه داد و این اصطلاح را به ادبیات سیاسی-فرهنگی ایران وارد کرد. او همچنین داستان‌نویس، مترجم و سفرنامه‌نویسی پرکار بود و همسرش سیمین دانشور، نویسنده‌ی نامدار، بود. آثار و اندیشه‌ی او تأثیر عمیقی بر نسل روشنفکران پیش از انقلاب گذاشت.",
"درگذشت جلیل شهناز، از سرشناس‌ترین نوازندگان تار و سه تار سدهٔ اخیر در ایران": "جلیل شهناز (۱۳۰۰-۱۳۹۲ خورشیدی) با شیوه‌ی منحصربه‌فرد خود در نوازندگی تار، سبکی تازه و تأثیرگذار در موسیقی سنتی ایران بنیان نهاد. او در طول دوران فعالیت طولانی خود با بسیاری از خوانندگان بزرگ موسیقی ایرانی همکاری کرد و به‌عنوان یکی از استادان بی‌بدیل ساز تار شناخته می‌شود.",
"درگذشت حسین منزوی شاعر نامدار ایرانی": "حسین منزوی (۱۳۲۵-۱۳۸۳ خورشیدی) از غزل‌سرایان برجسته‌ی نیمه‌ی دوم سده‌ی بیستم ایران بود که با ترکیب قالب کلاسیک غزل و مضامین و زبان امروزی، این قالب کهن را بازآفرینی کرد. اشعار عاشقانه‌ی او با زبانی صمیمی و پرشور از محبوب‌ترین غزل‌های معاصر فارسی‌اند.",
"درگذشت دکتر محمد مصدق": "محمد مصدق (۱۲۶۱-۱۳۴۵ خورشیدی)، نخست‌وزیر ایران در سال‌های ۱۳۳۰ تا ۱۳۳۲، رهبری جنبش ملی‌شدن صنعت نفت را برعهده داشت که به ملی‌کردن شرکت نفت ایران و انگلیس انجامید. او در پی کودتای ۲۸ مرداد ۱۳۳۲ (که با دخالت آمریکا و بریتانیا صورت گرفت) از قدرت برکنار و سال‌های پایانی عمر را در حصر خانگی در احمدآباد گذراند. مصدق همچنان یکی از نمادهای اصلی ناسیونالیسم و مبارزه با استعمار در تاریخ معاصر ایران است.",
"درگذشت ذبیح‌الله صفا، پژوهشگر، مترجم و استاد ممتاز دانشگاه تهران": "ذبیح‌الله صفا (۱۲۹۰-۱۳۷۸ خورشیدی) استاد دانشگاه تهران و پژوهشگری پرکار در حوزه‌ی ادبیات و تاریخ ایران بود. مهم‌ترین اثر او، مجموعه‌ی چندجلدی «تاریخ ادبیات در ایران»، هنوز یکی از اصلی‌ترین مراجع پژوهش در ادب فارسی محسوب می‌شود.",
"درگذشت ستارخان ملقب به سردار ملی از سرداران جنبش مشروطه ایران": "ستارخان (حدود ۱۲۴۶-۱۲۹۳ خورشیدی) در جریان جنگ داخلیِ پس از به‌توپ‌بستن مجلس (۱۲۸۷)، دفاع از تبریز را در برابر نیروهای استبدادطلب رهبری کرد و به‌پاس این پایداری، لقب «سردار ملی» گرفت. مقاومت او و همرزمانش نقشی تعیین‌کننده در بازگرداندن مشروطیت داشت و او را به یکی از ماندگارترین نمادهای مقاومت مردمی در تاریخ معاصر ایران بدل کرده است.",
"درگذشت سعید نفیسی، نویسنده، ادیب، تاریخ‌نگار، مترجم و شاعر ایرانی": "سعید نفیسی (۱۲۷۴-۱۳۴۵ خورشیدی) پژوهشگر و نویسنده‌ای بسیار پرکار بود که آثارش طیف گسترده‌ای از تاریخ، ادبیات و ترجمه را دربرمی‌گرفت. او استاد دانشگاه تهران بود و پژوهش‌های ارزنده‌ای درباره‌ی شخصیت‌هایی چون رودکی و خیام از خود برجای گذاشت.",
"درگذشت سهراب سپهری شاعر و نقاش ایرانی": "سهراب سپهری (۱۳۰۷-۱۳۵۹ خورشیدی) شاعری در سنت شعر نوی نیمایی و هم‌زمان نقاشی صاحب‌سبک بود. شعر بلند «صدای پای آب» او، با نگاهی عرفانی و ساده به طبیعت و هستی، از آثار محبوب شعر معاصر فارسی است؛ نقاشی‌های او نیز ترکیبی از زیبایی‌شناسی ایرانی و شرق دور را نشان می‌دهند.",
"درگذشت سید محمدحسین شهریار شاعر نامدار ایرانی": "سید محمدحسین شهریار (۱۲۸۵-۱۳۶۷ خورشیدی) یکی از مشهورترین شاعران سده‌ی بیستم ایران بود که هم به فارسی و هم به ترکی آذربایجانی شعر می‌سرود. منظومه‌ی «حیدربابایه سلام» او، سروده به ترکی و آکنده از دلتنگی برای زادگاهش، از محبوب‌ترین آثار شعری معاصر در میان فارسی‌زبانان و ترک‌زبانان ایران است.",
"درگذشت شیخ بهایی دانشمند عصر صفوی": "شیخ بهاءالدین عاملی، معروف به شیخ بهایی (۹۵۳-۱۰۳۰ هجری قمری)، دانشمندی چندبعدی در دوران صفوی بود: هم‌زمان فقیه، ریاضی‌دان، معمار و شاعر. او در طراحی برخی سازه‌های اصفهانِ دوران شاه‌عباس، از جمله بخش‌هایی از مسجد شیخ‌لطف‌الله، نقش داشت و آثاری در ریاضیات و نجوم نیز از او برجای مانده است.",
"درگذشت عبدالحسین زرین‌کوب خوانساری، ادیب، تاریخ‌نگار و منتقد ادبی برجسته ایران": "عبدالحسین زرین‌کوب (۱۳۰۱-۱۳۷۸ خورشیدی) در حوزه‌های گوناگون تاریخ و ادب ایران آثار ماندگاری از خود برجای گذاشت. کتاب معروف او «دو قرن سکوت» به بررسی سده‌های نخست پس از حمله‌ی اعراب به ایران می‌پردازد و از آثار پرخواننده و بحث‌برانگیز تاریخ‌نگاری ایران است.",
"درگذشت علی تجویدی، نوازندهٔ ویولن و سه‌تار و آهنگساز ایرانی": "علی تجویدی (۱۲۹۸-۱۳۸۹ خورشیدی) نوازنده و آهنگسازی بود که ملودی‌های ماندگاری برای برخی از بزرگ‌ترین خوانندگان موسیقی سنتی ایران ساخت و در نواختن ویولن به شیوه‌ی ایرانی از استادان این ساز به‌شمار می‌رود.",
"درگذشت علینقی وزیری، موسیقی‌دان و آهنگ‌ساز ایرانی": "علی‌نقی وزیری (۱۲۶۶-۱۳۵۸ خورشیدی) پس از تحصیل موسیقی در اروپا، نخستین مدرسه‌ی موسیقی ملی ایران را بنیان نهاد و کوشید نت‌نویسی و نظریه‌ی موسیقی غربی را با سنت موسیقی ایرانی درآمیزد. او را باید یکی از بنیان‌گذاران آموزش نوین موسیقی در ایران دانست.",
"درگذشت غلامحسین درویش معروف به «درویش‌خان»، هنرمند نامی و استاد موسیقی ایرانی اواخر دورهٔ قاجاریه": "غلامحسین درویش، ملقب به درویش‌خان (۱۲۵۱-۱۳۰۵ خورشیدی)، از استادان بزرگ تار و سه‌تار اواخر دوران قاجار بود که به او نسبت رواج و تثبیت قالب «تصنیف» در موسیقی ایرانی داده می‌شود. او در یک سانحه‌ی رانندگی درگذشت.",
"درگذشت غیاث‌الدین جمشید کاشانی ریاضیدان و اخترشناس ایرانی": "غیاث‌الدین جمشید کاشانی (حدود ۷۹۰-۸۳۲ هجری قمری) ریاضی‌دان و اخترشناسی بود که در رصدخانه‌ی الغ‌بیگ در سمرقند فعالیت می‌کرد. او عدد پی را با دقتی بی‌سابقه برای دوران خود (تا ۱۶ رقم اعشار) محاسبه کرد و در توسعه‌ی کسرهای اعشاری پیشگام بود.",
"درگذشت فریدون مشیری شاعر ایرانی": "فریدون مشیری (۱۳۰۵-۱۳۷۹ خورشیدی) از شاعران محبوب سبک نوی فارسی بود که با زبانی ساده و صمیمی، مضامین عاطفی و اجتماعی را در قالب شعر بیان می‌کرد؛ بسیاری از سروده‌های او به آهنگ نیز درآمده‌اند.",
"درگذشت محمد زکریای رازی پزشک، فیلسوف و شیمیدان ایرانی.": "محمد بن زکریای رازی (۲۵۱-۳۱۳ هجری قمری) پزشک، فیلسوف و شیمی‌دانی برجسته بود که کتاب «الحاوی» او دانشنامه‌ای جامع در طب به‌شمار می‌رفت. او نخستین کسی بود که آبله را به‌طور بالینی از سرخک تشخیص و تمایز داد و در شیمی نیز پژوهش‌های پیشگامانه‌ای (از جمله در جداسازی الکل و اسید سولفوریک) انجام داد. او ریاست بیمارستان‌های ری و بغداد را برعهده داشت.",
"درگذشت محمدرضا لطفی، نوازندهٔ برجسته و سرشناس تار، سه‌تار و ردیف‌دان، موسیقی‌دان و آهنگساز": "محمدرضا لطفی (۱۳۲۶-۱۳۹۳ خورشیدی) از استادان تار و سه‌تار بود که گروه‌های «شیدا» و «عارف» را برای احیای اجرای گروهی موسیقی سنتی ایران در دهه‌های ۱۳۵۰ و ۱۳۶۰ بنیان نهاد. او همچنین از پژوهشگران و مدرسان برجسته‌ی ردیف موسیقی ایرانی بود.",
"درگذشت محمود حسابی فیزیکدان، سناتور، وزیر آموزش و پرورش و بنیانگذار دانشگاهی در ایران": "محمود حسابی (۱۲۸۲-۱۳۷۱ خورشیدی) پس از تحصیل و کار در فرانسه، دانشکده‌ی فیزیک دانشگاه تهران را بنیان نهاد و مدتی نیز سناتور و وزیر فرهنگ بود. او یکی از چهره‌های نمادین علم مدرن در ایران به‌شمار می‌رود و برخی نظریات اولیه‌ی او در فیزیک ذرات، هرچند محل بحث میان کارشناسان است، به نامش شهرت یافته.",
"درگذشت مریم میرزاخانی، ریاضیدان ایرانی و اولین زن برنده مدال فیلدز": "مریم میرزاخانی (۱۳۵۶-۱۳۹۶ خورشیدی) در سال ۲۰۱۴ میلادی، به‌پاس پژوهش‌هایش درباره‌ی هندسه و سیستم‌های دینامیکی روی سطوح ریمان، نخستین زن و نخستین ایرانی برنده‌ی مدال فیلدز -معتبرترین جایزه‌ی ریاضیات جهان- شد. او استاد دانشگاه استنفورد بود و در چهل‌سالگی بر اثر سرطان پستان درگذشت؛ خبر مرگش موجی از تأثر در سراسر جهان علمی برانگیخت و پژوهش‌های او همچنان در مرکز توجه ریاضی‌دانان قرار دارد.",
"درگذشت مهدی حمیدی شیرازی، ادیب، شاعر، مترجم و منتقد ایرانی": "مهدی حمیدی شیرازی (۱۲۹۳-۱۳۶۵ خورشیدی) از شاعران سبک نوکلاسیک بود که میان فرم کلاسیک شعر فارسی و مضامین امروزی پل زد و سال‌ها نیز به تدریس ادبیات فارسی در دانشگاه پرداخت.",
"درگذشت نیما یوشیج پدر شعر نو پارسی": "علی اسفندیاری، معروف به نیما یوشیج (۱۲۷۴-۱۳۳۸ خورشیدی)، با کنارگذاشتن قواعد ثابت وزن و قافیه‌ی شعر کلاسیک، جنبش «شعر نو» را در ادبیات فارسی بنیان نهاد. تأثیر او بر تقریباً تمام شاعران بزرگ سده‌ی بیستم ایران -از شاملو و اخوان ثالث تا فروغ فرخزاد- چنان عمیق است که او را «پدر شعر نو پارسی» می‌نامند.",
"درگذشت هاراطون داویدیان بنیانگذار روانپزشکی درایران": "هاراطون داویدیان، روان‌پزشک ارمنی‌تبار ایرانی، از پیشگامان تأسیس مراکز نوین درمان روانی در ایران بود و نقش مهمی در شکل‌گیری روان‌پزشکی به‌عنوان یک رشته‌ی تخصصی مدرن در کشور داشت.",
"درگذشت هانیبال الخاص، نقاش و مجسمه ساز ایرانی": "هانیبال الخاص (۱۳۰۹-۱۳۸۹ خورشیدی) نقاشی تأثیرگذار بود که «کارگاه آزاد نقاشی» او طی دهه‌ها میزبان و مربی نسل‌های متعددی از هنرمندان نقاشی معاصر ایران شد. سبک بیانگرا و پرقدرت او در نقاشی فیگوراتیو شاخصه‌ی آثارش بود.",
"درگذشت هوشنگ سیحون معمار، طراح، نقاش و مجسمه‌ساز ایرانی": "هوشنگ سیحون (۱۲۹۹-۱۳۹۳ خورشیدی) معماری بود که طراحی آرامگاه‌های خیام در نیشابور، کمال‌الملک، و ابن سینا در همدان را برعهده داشت. آثار او با ترکیب عناصر معماری مدرن و نمادهای سنتی ایرانی، از شاخص‌ترین بناهای یادبود فرهنگی ایران معاصرند.",
"درگذشت پرویز مشکاتیان موسیقی‌دان و نوازنده ایرانی": "پرویز مشکاتیان (۱۳۳۴-۱۳۸۸ خورشیدی) از استادان برجسته‌ی سنتور و از چهره‌های اصلی احیای موسیقی سنتی ایران در دهه‌های پس از انقلاب بود. او با همکاری محمدرضا شجریان اثر ماندگار «بیداد» را خلق کرد و گروه‌های موسیقی متعددی را رهبری کرد.",
"درگذشت پروین اعتصامی": "پروین اعتصامی (۱۲۸۶-۱۳۲۰ خورشیدی) از نخستین زنان شاعر برجسته‌ی ادب معاصر فارسی بود که با سرودن قطعات اخلاقی و آموزنده در قالب‌های سنتی، جایگاهی ویژه در شعر معاصر یافت. او در سنین جوانی و بر اثر بیماری تیفوس درگذشت.",
"درگذشت کارو لوکس، از پژوهشگران به‌نام سیستم‌های هوشمند در ایران، «پدر علم رباتیک ایران»": "کارو لوکس از پیشگامان پژوهش در حوزه‌ی رباتیک و سیستم‌های هوشمند در ایران بود و به همین دلیل لقب «پدر علم رباتیک ایران» گرفته است؛ فعالیت‌های او پایه‌گذار توسعه‌ی این حوزه در کشور بوده است.",
"درگذشت کیخسرو شاهرخ، بنیانگذار آرامگاه فردوسی و کتابخانه مجلس شورای ملی و مدیر عامل شرکت سهامی تلفن": "کیخسرو شاهرخ (۱۲۵۳-۱۳۱۹ خورشیدی) از چهره‌های برجسته‌ی جامعه‌ی زرتشتی ایران و نماینده‌ی این اقلیت دینی در مجلس شورای ملی بود. او در ساخت آرامگاه فردوسی در توس و سازمان‌دهی کتابخانه‌ی مجلس نقش داشت و مدیریت شرکت سهامی تلفن را نیز برعهده گرفت.",
"روز بزرگداشت ابوالفضل بیهقی، تاریخ‌نگار و نویسنده ایرانی": "ابوالفضل بیهقی (۳۸۵-۴۷۰ هجری قمری) دبیر دیوان غزنویان بود که کتاب «تاریخ بیهقی» را درباره‌ی دوران سلطان مسعود غزنوی نوشت. این اثر به‌سبب نثر روان و روایت زنده و پرجزئیاتش، یکی از شاهکارهای مسلم نثر تاریخ‌نگاری فارسی به‌شمار می‌رود.",
"روز بزرگداشت ابوریحان بیرونی": "ابوریحان بیرونی (۳۶۲-۴۴۰ هجری قمری)، دانشمند هم‌عصر ابن سینا، شعاع کره‌ی زمین را با دقتی چشمگیر برای دوران خود محاسبه کرد. او در کتاب «تحقیق ماللهند» به بررسی عمیق فرهنگ و علوم هند پرداخت و آثار مهمی نیز در گاه‌شماری، کانی‌شناسی و ریاضیات از خود برجای گذاشت.",
"روز بزرگداشت ابوعلی سینا و روز پزشک": "این روز هم‌زمان با یادبود ابوعلی سینا -نویسنده‌ی کتاب تأثیرگذار «قانون در طب»- به‌عنوان روز پزشک نیز در تقویم ایران نام‌گذاری شده است، اشاره‌ای نمادین به جایگاه او در تاریخ طب.",
"روز بزرگداشت اختر چرخ ادب، پروین اعتصامی": "«اختر چرخ ادب» لقبی است که منتقدان به پروین اعتصامی، از نخستین و برجسته‌ترین زنان شاعر ادب معاصر فارسی، داده‌اند؛ اشعار اخلاقی و آموزنده‌ی او در قالب‌های کلاسیک همچنان از سرمایه‌های ادبیات فارسی به‌شمار می‌روند.",
"روز بزرگداشت حافظ": "خواجه شمس‌الدین محمد حافظ شیرازی (حدود ۷۲۷-۷۹۲ هجری قمری) با دیوان غزلیاتش جایگاهی بی‌مانند در فرهنگ ایرانی یافته است؛ کتابی که در بسیاری از خانه‌های ایرانی همراه قرآن نگه‌داری و برای فال‌گیری («فال حافظ») گشوده می‌شود. آرامگاه او در شیراز، حافظیه، از مهم‌ترین زیارتگاه‌های ادبی جهان فارسی‌زبان است.",
"روز بزرگداشت حکیم عمر خیام": "عمر خیام نیشابوری (۴۲۷-۵۱۰ هجری قمری) هم‌زمان ریاضی‌دان، اخترشناس و شاعر بود. او به دستور ملک‌شاه سلجوقی تقویم جلالی را طراحی کرد که دقتی حتی بیش از تقویم گرگوری امروزی دارد؛ در ریاضیات نیز در حل معادلات درجه‌ی سوم پیشگام بود. رباعیات خیام از طریق ترجمه‌ی ادوارد فیتزجرالد به انگلیسی، شهرتی جهانی یافتند.",
"روز بزرگداشت خاقانی شروانی": "خاقانی شروانی (۵۲۰-۵۹۵ هجری قمری) شاعر اهل شروان بود که به‌سبب قصاید پیچیده و پرمضمونش شهرت دارد. مشهورترین اثر او، قصیده‌ی «ایوان مدائن»، مرثیه‌ای است بر ویرانه‌های کاخ ساسانیِ تیسفون که نمادی از زوال شکوه گذشته‌ی ایران است.",
"روز بزرگداشت خواجه نصیر الدین طوسی و روز مهندس": "خواجه نصیرالدین طوسی (۵۹۷-۶۷۲ هجری قمری) فیلسوف، ریاضی‌دان و اخترشناسی بود که با حمایت هلاکوخان مغول، رصدخانه‌ی مراغه را بنیان نهاد و دانشمندانی از سرزمین‌های گوناگون را گرد هم آورد. او ابزار ریاضی موسوم به «زوج طوسی» را ابداع کرد که سده‌ها بعد در نجوم کوپرنیک نیز کاربرد یافت؛ کتاب «اخلاق ناصری» او نیز از متون کلاسیک اخلاق در تمدن اسلامی است.",
"روز بزرگداشت سعدی": "مصلح‌الدین سعدی شیرازی (حدود ۶۰۶-۶۹۱ هجری قمری) در «بوستان» (منظوم) و «گلستان» (آمیزه‌ی نظم و نثر)، حکمت عملی زندگی را در قالب حکایت‌های کوتاه و اندرزهای اخلاقی بیان کرد. بیت معروف او درباره‌ی یگانگی بنی‌آدم، امروز حتی بر سردر ساختمان سازمان ملل متحد نیز نقش بسته است.",
"روز بزرگداشت شمس تبریزی": "شمس‌الدین تبریزی (حدود ۵۸۲-۶۴۵ هجری قمری) عارفی سرگردان بود که دیدارش با مولانا جلال‌الدین بلخی در قونیه، مسیر زندگی این فقیه محترم را به‌کلی دگرگون کرد و او را به یکی از بزرگ‌ترین شاعران عارف تاریخ بدل ساخت. ناپدیدشدن مرموز شمس (که به قتل او نیز مظنون‌اند) تا پایان عمر مولانا را در اندوهی عمیق نگاه داشت.",
"روز بزرگداشت شیخ بهایی": "شیخ بهاءالدین عاملی (۹۵۳-۱۰۳۰ هجری قمری)، دانشمند دوران صفوی، هم‌زمان فقیه، ریاضی‌دان، معمار و شاعر بود و در طراحی بخش‌هایی از بناهای اصفهانِ عصر شاه‌عباس نقش داشت.",
"روز بزرگداشت شیخ شهاب الدین سهروردی": "شهاب‌الدین سهروردی (۵۴۹-۵۸۷ هجری قمری) بنیان‌گذار مکتب فلسفی اشراق بود که فلسفه‌ی مشایی را با نمادگرایی نور برگرفته از اندیشه‌ی ایران باستان درآمیخت. او در حلب به اتهام بدعت اعدام شد و از همین رو به «شیخ مقتول» شهرت یافت.",
"روز بزرگداشت صائب تبریزی": "صائب تبریزی (۱۰۰۰-۱۰۸۷ هجری قمری) پرکارترین و برجسته‌ترین شاعر سبک هندی در شعر فارسی بود؛ بیش از سیصدهزار بیت به او نسبت داده می‌شود. او مدتی در دربار گورکانیان هند اقامت داشت و اشعارش به‌سبب تصویرسازی‌های ظریف و نکته‌های فلسفی شهرت دارند.",
"روز بزرگداشت عطار نیشابوری": "فریدالدین عطار نیشابوری (حدود ۵۴۰-۶۱۸ هجری قمری) در منظومه‌ی «منطق‌الطیر»، سفر نمادین مرغان به‌سوی سیمرغ را به‌عنوان تمثیلی از سیر و سلوک عرفانی روایت کرد. تأثیر او بر مولانا بسیار عمیق بوده و بنا بر روایات تاریخی، در جریان حمله‌ی مغول به نیشابور کشته شد.",
"روز بزرگداشت فردوسی": "ابوالقاسم فردوسی (۳۲۹-۴۱۶ هجری قمری) نزدیک به سی سال از عمر خود را وقف سرودن شاهنامه کرد، حماسه‌ای در پنجاه‌هزار بیت که اسطوره‌ها و تاریخ ایران پیش از اسلام را حفظ کرده است. تلاش او در سرودن این اثر عظیم به زبان فارسی، سهم بزرگی در بقا و تقویت این زبان پس از ورود اسلام به ایران داشت.",
"روز بزرگداشت محمدبن زکریای رازی و روز داروساز": "این روز هم‌زمان با یادبود محمد بن زکریای رازی -پزشک و شیمی‌دان بزرگ ایرانی- به‌عنوان روز داروساز نیز در تقویم ایران گرامی داشته می‌شود.",
"روز بزرگداشت ملاصدرا": "صدرالدین محمد شیرازی، معروف به ملاصدرا (۹۸۰-۱۰۵۰ هجری قمری)، با فلسفه‌ی «حکمت متعالیه»، فلسفه‌ی مشاء، حکمت اشراق و عرفان اسلامی را در نظامی واحد ترکیب کرد. مهم‌ترین اثر او، «الاسفار الاربعه»، او را به یکی از تأثیرگذارترین فیلسوفان تاریخ اسلام بدل کرده است.",
"روز بزرگداشت یعقوب لیث صفاری (رادمان پورماهک) نخستین پادشاه ایرانی پس از اسلام": "یعقوب لیث صفاری (حدود ۲۰۰-۲۶۵ هجری قمری) از شغل مسگری («صفار») به فرماندهی نظامی رسید و سلسله‌ی صفاریان را بنیان نهاد؛ نخستین حکومت مستقل ایرانی پس از فتح اعراب. بنا بر روایتی مشهور، هنگامی که شاعران دربارش به عربی شعر می‌سرودند و او آن‌ها را درنمی‌یافت، خواستار سرودن اشعار به زبان فارسی شد که این را گامی نمادین در احیای زبان فارسی در دربار دانسته‌اند.",
"روز دانشجو": "روز دانشجو، ۱۶ آذر، یادآور کشته‌شدن سه دانشجوی دانشگاه تهران (بزرگ‌نیا، قندچی و شریعت‌رضوی) توسط نیروی انتظامی در آذر ۱۳۳۲ است؛ درست پس از کودتای ۲۸ مرداد، در جریان اعتراض دانشجویان به سفر معاون‌رئیس‌جمهور وقت آمریکا (نیکسون) به ایران. این رویداد از آن پس به نمادی برای فعالیت سیاسی دانشجویی در ایران بدل شده است.",
"روز شعر و ادب پارسی و روز بزرگداشت استاد شهریار": "این روز هم‌زمان با زادروز سید محمدحسین شهریار، شاعر بلندآوازه‌ی سراینده‌ی منظومه‌ی «حیدربابایه سلام»، به‌عنوان روز شعر و ادب پارسی نیز نام‌گذاری شده است.",
"روز علوم آزمایشگاهی، زاد‌روز حکیم سید اسماعیل جرجانی": "سید اسماعیل جرجانی (۴۳۴-۵۳۱ هجری قمری) پزشکی بود که کتاب «ذخیره خوارزمشاهی» را -دانشنامه‌ای پزشکی به زبان فارسی به‌جای عربی، امری غیرمعمول در آن دوران- برای دربار خوارزمشاهیان نوشت؛ اثری که سهم مهمی در گسترش واژگان علمی فارسی داشت.",
"روز ملی شدن صنعت نفت ایران": "در اسفند ۱۳۲۹، مجلس شورای ملی ایران به رهبری دکتر محمد مصدق، طرح ملی‌شدن صنعت نفت را تصویب کرد و صنعت نفت که تا پیش از آن در انحصار شرکت نفت ایران و انگلیس بود، تحت مالکیت ملی ایران درآمد. این اقدام یکی از نمادین‌ترین لحظات مبارزه با استعمار اقتصادی در تاریخ معاصر ایران و خاورمیانه به‌شمار می‌رود.",
"روز پاسداشت زبان فارسی": "روز پاسداشت زبان فارسی هم‌زمان با یادبود زادروز فردوسی -شاعری که سهمی بی‌بدیل در حفظ و تقویت زبان فارسی پس از ورود اسلام داشت- نام‌گذاری شده تا توجه عمومی را به اهمیت پاسداری از این زبان جلب کند.",
"روز پیروزی کاوه و فریدون بر ضحاک": "بر پایه‌ی روایت شاهنامه، ضحاک ماردوش، پادشاهی ستمگر که دو مار بر شانه‌هایش روییده و هر روز باید با مغز جوانان تغذیه می‌شدند، سرانجام با قیام کاوه‌ی آهنگر -که پرچمش (درفش کاویانی) به نماد ملی ایران بدل شد- و به یاری فریدون، شاهزاده‌ی راستین، سرنگون شد. این افسانه از دیرباز تمثیلی از پیروزی عدالت بر ستم در فرهنگ ایرانی بوده است.",
"روز گل محمدی و گلاب": "این روز، سنت دیرینه‌ی گلاب‌گیری در کاشان را گرامی می‌دارد؛ صنعتی که هرساله در فصل بهار با برداشت گل محمدی (گل سرخ دمشقی) و تقطیر آن انجام می‌شود و کاشان را به یکی از مراکز مهم تولید گلاب و عطریات گیاهی ایران بدل کرده است.",
"روزبزرگداشت مولوی": "جلال‌الدین محمد بلخی، معروف به مولانا یا مولوی (۶۰۴-۶۷۲ هجری قمری)، در بلخ زاده شد و در قونیه ساکن شد. او مثنوی معنوی -منظومه‌ای شش‌جلدی در حکمت و عرفان- و دیوان شمس -مجموعه‌ی غزلیات پرشور الهام‌گرفته از شمس تبریزی- را سرود و امروز یکی از پرخواننده‌ترین شاعران جهان به‌شمار می‌رود؛ طریقت مولویه (درویشان چرخان) نیز از میراث معنوی اوست.",
"زادروز آشو زرتشت، اَبَراِنسان بزرگ تاریخ": "زرتشت، پیامبر یکی از کهن‌ترین ادیان یکتاپرستانه‌ی جهان، بنیان‌گذار آموزه‌ی «پندار نیک، گفتار نیک، کردار نیک» بود. دوران دقیق زندگی او همچنان میان پژوهشگران محل بحث است (برخی برآوردها آن را تا هزاره‌ی دوم پیش از میلاد نیز عقب می‌برند) اما سروده‌های منسوب به او، گاهان، هسته‌ی اصلی کتاب مقدس اوستا را تشکیل می‌دهند.",
"زادروز آیدین آغداشلو نقاش، نویسنده، منتقد فیلم و طراح هنرمند ایرانی": "آیدین آغداشلو (زاده‌ی ۱۳۱۹ خورشیدی) نقاش، منتقد و پژوهشگر هنری تأثیرگذاری در جریان هنر معاصر ایران است که هم به‌عنوان هنرمند و هم به‌عنوان مرمت‌گر و نظریه‌پرداز تاریخ هنر شناخته می‌شود.",
"زادروز ابراهیم گلستان کارگردان، نخستین برندهٔ یک جایزه بین‌المللی برای سینمای ایران": "ابراهیم گلستان (۱۳۰۱-۱۴۰۲ خورشیدی) از پیشگامان سینمای مستند و داستانی نوین ایران بود و نخستین ایرانی به‌شمار می‌رود که جایزه‌ای بین‌المللی سینمایی (برای فیلمی مستند) دریافت کرد. او همچنین نویسنده و مترجمی برجسته بود.",
"زادروز ابن سینا پزشک و شاعر و از مشهورترین و تاثیرگذارترینِ فیلسوفان و دانشمندان ایران‌زمین": "ابوعلی سینا (۳۷۰-۴۲۸ هجری قمری) با کتاب «قانون در طب»، که سده‌ها در دانشگاه‌های اروپا تدریس می‌شد، و «کتاب شفا» در فلسفه، یکی از تأثیرگذارترین دانشمندان تاریخ بشر است. گستره‌ی دانش او از پزشکی و فلسفه تا منطق و حتی شعر را دربرمی‌گرفت.",
"زادروز ابوالحسن صبا موسیقیدان، آهنگساز و نوازندهٔ سرشناس ایرانی": "ابوالحسن صبا (۱۲۸۱-۱۳۳۶ خورشیدی) نوازنده‌ای چیره‌دست بر چند ساز (ویولن، سنتور، کمانچه) و از تأثیرگذارترین چهره‌های موسیقی سنتی ایران در سده‌ی بیستم بود. او بخش بزرگی از ردیف موسیقی ایرانی را ثبت و منظم کرد و مدرسه‌ای برای آموزش موسیقی بنیان نهاد.",
"زادروز ابوریحان بیرونی دانشمند بزرگ، ریاضی‌دان، ستاره‌شناس، تقویم‌شناس، انسان‌شناس، هندشناس و تاریخ‌نگار بزرگ ایرانی": "ابوریحان بیرونی (۳۶۲-۴۴۰ هجری قمری) در کتاب «آثارالباقیه» به بررسی تطبیقی تقویم‌های گوناگون جهان پرداخت و در «تحقیق ماللهند» شناختی عمیق از فرهنگ و علوم شبه‌قاره‌ی هند ارائه داد؛ گستره‌ی دانش او از ریاضیات و نجوم تا کانی‌شناسی و مردم‌شناسی را دربرمی‌گرفت.",
"زادروز احمد شاملو شاعر و نویسنده و مترجم ایرانی": "احمد شاملو (۱۳۰۴-۱۳۷۹ خورشیدی) با پیشگامی در «شعر سپید» (شعری فارغ از وزن عروضی سنتی)، گامی مهم فراتر از شعر نیمایی در ادبیات فارسی برداشت. او مترجمی پرکار، روزنامه‌نگار و گردآورنده‌ی فرهنگ لغت عامیانه‌ی «کتاب کوچه» نیز بود.",
"زادروز احمد محمود نویسندهٔ معاصر ایرانی": "احمد محمود (۱۳۱۰-۱۳۸۱ خورشیدی) رمان‌نویسی بود که با آثار رئالیستی-اجتماعی خود، به‌ویژه رمان «همسایه‌ها»، زندگی طبقه‌ی کارگر و مردم عادی جنوب ایران (خوزستان) را به تصویر کشید.",
"زادروز بابک خرمدین، سپه‌سالار دلاور ایران": "بابک خرمدین، رهبر جنبش خرمیان، بیش از دو دهه از دژ بذّ در آذربایجان علیه سلطه‌ی خلافت عباسی مقاومت مسلحانه کرد، پیش از آنکه با خیانت افشین اسیر و در سامرا اعدام شود. او همچنان نمادی از مقاومت ایرانیان در برابر سلطه‌ی خارجی است.",
"زادروز توران میرهادی استاد ادبیات کودک، نویسنده و کارشناس آموزش و پرورش و شخصیت برجسته فرهنگی": "توران میرهادی (۱۳۰۶-۱۳۹۵ خورشیدی) از بنیان‌گذاران شورای کتاب کودک در ایران بود و نقشی محوری در توسعه‌ی ادبیات و آموزش کودکان در کشور ایفا کرد.",
"زادروز جلیل شهناز، از سرشناس‌ترین نوازندگان تار و سه تار سدهٔ اخیر در ایران": "جلیل شهناز (۱۳۰۰-۱۳۹۲ خورشیدی) با شیوه‌ی منحصربه‌فرد خود در نوازندگی تار، سبکی تازه و تأثیرگذار در موسیقی سنتی ایران بنیان نهاد و با بسیاری از خوانندگان بزرگ موسیقی ایرانی همکاری کرد.",
"زادروز جلیل ضیاءپور، پدر نقاشی مدرن ایران": "جلیل ضیاءپور (۱۲۹۹-۱۳۷۸ خورشیدی) پس از تحصیل در پاریس، جنبش‌های هنری مدرن از جمله کوبیسم را به ایران معرفی کرد و نخستین نمایشگاه نقاشی مدرن ایران را برگزار کرد. او همچنین پژوهش‌های ارزشمندی درباره‌ی صنایع‌دستی و پارچه‌های سنتی ایرانی انجام داد.",
"زادروز حسین منزوی شاعر ایرانی": "حسین منزوی (۱۳۲۵-۱۳۸۳ خورشیدی) از غزل‌سرایان برجسته‌ی نیمه‌ی دوم سده‌ی بیستم بود که با ترکیب قالب کلاسیک غزل و زبان امروزی، این قالب کهن را بازآفرینی کرد.",
"زادروز داریوش مهرجویی کارگردان، نویسنده و مترجم ایرانی.": "داریوش مهرجویی (۱۳۱۸-۱۴۰۲ خورشیدی) با فیلم «گاو» (۱۳۴۸)، یکی از نقاط عطف موج نوی سینمای ایران را رقم زد. او در دوران فعالیت طولانی خود، هم پیش و هم پس از انقلاب، آثار تأثیرگذار متعددی ساخت.",
"زادروز ستارخان ملقب به سردار ملی و از سرداران جنبش مشروطه ایران": "ستارخان در جریان جنگ داخلیِ پس از به‌توپ‌بستن مجلس، دفاع از تبریز را در برابر نیروهای استبدادطلب رهبری کرد و به‌پاس این پایداری، لقب «سردار ملی» گرفت؛ مقاومت او نقشی تعیین‌کننده در بازگرداندن مشروطیت داشت.",
"زادروز سیمین دانشور نویسنده و مترجم ایرانی": "سیمین دانشور (۱۲۹۹-۱۳۹۰ خورشیدی) با رمان «سووشون» (۱۳۴۸)، یکی از نخستین رمان‌های مهم فارسی با روایتی از دیدگاه زنانه را نوشت. او همچنین مترجمی توانا و همسر جلال آل‌احمد بود.",
"زادروز عباس زریاب خویی، مترجم، تاریخ‌دان و کتاب‌شناس ایرانی": "عباس زریاب خویی (۱۲۹۸-۱۳۷۳ خورشیدی) از پژوهشگران برجسته‌ی تاریخ ایران و اسلام در سده‌ی بیستم بود و آثار تاریخی مهمی را نیز به فارسی ترجمه کرد.",
"زادروز غلامحسین بنان، خوانندهٔ ایرانی": "غلامحسین بنان (۱۲۹۰-۱۳۶۵ خورشیدی) یکی از اسطوره‌های آواز سنتی ایران در سده‌ی بیستم بود که به‌سبب تسلط و ظرافت بی‌نظیر صدایش، همچنان الگوی بسیاری از خوانندگان پس از خود است.",
"زادروز فردوسی": "ابوالقاسم فردوسی (۳۲۹-۴۱۶ هجری قمری) نزدیک به سی سال از عمر خود را وقف سرودن شاهنامه کرد، حماسه‌ای در پنجاه‌هزار بیت که اسطوره‌ها و تاریخ ایران پیش از اسلام را برای نسل‌های بعد حفظ کرده است.",
"زادروز فرشید مثقالی مجسمه‌ساز، گرافیست و تصویرگر کتاب کودک، اولین و تنها ایرانی برنده جایزه هانس کریستیان آندرسن": "فرشید مثقالی (زاده‌ی ۱۳۲۲ خورشیدی) در سال ۱۳۵۳ (۱۹۷۴ میلادی) جایزه‌ی هانس کریستیان آندرسن را دریافت کرد؛ معتبرترین جایزه‌ی بین‌المللی تصویرگری و ادبیات کودک، که تاکنون تنها او در میان ایرانیان به آن دست یافته است.",
"زادروز فرنگیس یگانگی بنیان‌گذار و نخستین مدیرعامل سازمان صنایع دستی ایران": "فرنگیس یگانگی بنیان‌گذار و نخستین مدیرعامل سازمان صنایع‌دستی ایران بود و نقش مهمی در سازمان‌دهی و معرفی صنایع‌دستی سنتی کشور در سطح ملی ایفا کرد.",
"زادروز فرهاد فخرالدینی موسیقیدان، رهبر ارکستر ملی ایران": "فرهاد فخرالدینی (زاده‌ی دهه‌ی ۱۳۲۰ خورشیدی) سال‌های متمادی رهبری ارکستر ملی ایران را برعهده داشت و در تنظیم آثار سازی موسیقی سنتی و فولکلور ایرانی برای اجرای ارکسترال نقشی برجسته ایفا کرده است.",
"زادروز فروغ فرخزاد شاعر ایرانی": "فروغ فرخزاد (۱۳۱۳-۱۳۴۵ خورشیدی) یکی از تأثیرگذارترین شاعران معاصر ایران بود که با صدایی شخصی و صریحِ زنانه، در اشعاری چون «گناه» و «تولدی دیگر»، هنجارهای اجتماعی زمانه‌اش را به چالش کشید. او همچنین فیلم مستند تحسین‌شده‌ی «خانه سیاه است» را ساخت و در سی‌ودوسالگی در سانحه‌ی رانندگی درگذشت.",
"زادروز فریدون مشیری شاعر ایرانی": "فریدون مشیری (۱۳۰۵-۱۳۷۹ خورشیدی) از شاعران محبوب سبک نوی فارسی بود که با زبانی ساده و صمیمی، مضامین عاطفی و اجتماعی را بیان می‌کرد.",
"زادروز قیصر امین‌پور نویسنده، مدرس دانشگاه و شاعر معاصرایرانی": "قیصر امین‌پور (۱۳۳۸-۱۳۸۶ خورشیدی) از شاعران برجسته‌ی نسل پس از انقلاب بود که در کنار سرایش شعر، به تدریس ادبیات فارسی در دانشگاه نیز می‌پرداخت.",
"زادروز لیلیت تریان مجسمه‌ساز ایرانی، مادر مجسمه‌سازی ایران": "لیلیت تریان، مجسمه‌ساز ارمنی‌تبار ایرانی، از پیشگامان مجسمه‌سازی نوین در ایران بود و به همین سبب به «مادر مجسمه‌سازی ایران» شهرت یافته است.",
"زادروز محسن هشترودی ریاضی‌دان، فیلسوف و شاعر ایرانی.": "محسن هشترودی (۱۲۸۶-۱۳۵۵ خورشیدی) پس از تحصیل ریاضیات در فرانسه، استاد دانشگاه تهران شد و به یکی از برجسته‌ترین ریاضی‌دانان ایران در سده‌ی بیستم بدل گشت. او در کنار فعالیت علمی، شعر نیز می‌سرود و به فلسفه علاقه داشت.",
"زادروز محمد اقبال شاعر و فیلسوف بزرگ زبان فارسی": "محمد اقبال لاهوری (۱۲۵۶-۱۳۱۶ خورشیدی)، فیلسوف و شاعر اهل شبه‌قاره‌ی هند (پاکستان امروزی)، بخش قابل‌توجهی از آثار خود را به زبان فارسی و با الهام از مولانا سرود. او را پدر معنوی اندیشه‌ی تأسیس پاکستان می‌دانند و در ایران نیز جایگاهی والا دارد.",
"زادروز محمد خوارزمی، ریاضیدان و فیلسوف ایرانی و روز ملی فناوری اطلاعات": "محمد بن موسی خوارزمی (حدود ۱۶۴-۲۳۲ هجری قمری) در بیت‌الحکمه‌ی بغداد فعالیت می‌کرد و کتاب او درباره‌ی جبر («الجبر») نام خود را به این شاخه از ریاضیات داد. صورت لاتین‌شده‌ی نامش («الگوریتمی») منشأ واژه‌ی «الگوریتم» در زبان‌های اروپایی است.",
"زادروز محمدتقی بهار ملقب به ملک‌الشعرا، شاعر، ادیب، نویسنده و سیاست‌مدار ایرانی": "محمدتقی بهار، ملقب به ملک‌الشعرا (۱۲۶۵-۱۳۳۰ خورشیدی)، شاعر و روزنامه‌نگار فعال دوران مشروطه بود که بعدها استاد دانشگاه و وزیر نیز شد. کتاب «سبک‌شناسی» او پژوهشی بنیادین درباره‌ی سیر تحول نثر فارسی است.",
"زادروز محمدرضا شجریان خواننده، موسیقی‌دان و خوشنویس ایرانی": "محمدرضا شجریان (۱۳۱۹-۱۳۹۹ خورشیدی) شناخته‌شده‌ترین آوازخوان موسیقی سنتی ایران در دوران معاصر بود که به‌سبب تسلط بر ردیف و اجرای پراحساس آن، محبوبیتی فراگیر و فرا‌نسلی یافت. او خوشنویسی چیره‌دست نیز بود.",
"زادروز مریم میرزاخانی ریاضیدان ایرانی، اولین زن برندهٔ جایزه فیلدز": "مریم میرزاخانی در سال ۲۰۱۴ میلادی، برای پژوهش درباره‌ی هندسه و سیستم‌های دینامیکی روی سطوح ریمان، نخستین زن و نخستین ایرانی برنده‌ی مدال فیلدز -معتبرترین جایزه‌ی ریاضیات جهان- شد.",
"زادروز منصور نریمان نوازندهٔ بربط، آهنگساز، ردیف‌دان، پژوهشگر موسیقی سنتی ایران و پدر عود ایران": "منصور نریمان را به‌سبب تلاش‌هایش در احیای جایگاه ساز عود (بربط) در موسیقی سنتی ایران، «پدر عود ایران» می‌نامند؛ او همچنین پژوهشگر و ردیف‌دان موسیقی ایرانی بود.",
"زادروز نیما یوشیج پدر شعر نو پارسی": "نیما یوشیج با کنارگذاشتن قواعد ثابت وزن و قافیه‌ی شعر کلاسیک، جنبش «شعر نو» را در ادبیات فارسی بنیان نهاد و تأثیری عمیق بر تقریباً تمام شاعران بزرگ سده‌ی بیستم ایران گذاشت.",
"زادروز پرویز مشکاتیان آهنگساز، موسیقی‌دان و نوازندهٔ سنتور": "پرویز مشکاتیان از استادان برجسته‌ی سنتور و از چهره‌های اصلی احیای موسیقی سنتی ایران در دهه‌های پس از انقلاب بود و اثر ماندگار «بیداد» را با همکاری محمدرضا شجریان خلق کرد.",
"زادروز پرویز یاحقی، نوازنده‌‌ی چیره‌دست ویلون؛ موسیقیدان و آهنگساز ایرانی": "پرویز یاحقی از نوازندگان برجسته‌ی ویولن در موسیقی سنتی و نیمه‌کلاسیک ایران در سده‌ی بیستم بود و در ساخت ملودی‌های محبوب آن دوران نقش داشت.",
"زادروز پروین اعتصامی شاعر ایرانی": "پروین اعتصامی از نخستین زنان شاعر برجسته‌ی ادب معاصر فارسی بود که با سرودن قطعات اخلاقی و آموزنده در قالب‌های سنتی، جایگاهی ویژه در شعر معاصر یافت.",
"زادروز کوروش بزرگ": "کوروش بزرگ (حدود ۶۰۰-۵۳۰ پیش از میلاد)، بنیان‌گذار شاهنشاهی هخامنشی، یکی از بزرگ‌ترین امپراتوری‌های تاریخ را با ترکیبی از فتح نظامی و مدیریت نسبتاً بردبارانه‌ی اقوام مطیع بنا نهاد. استوانه‌ی گلی منسوب به او، معروف به استوانه‌ی کوروش، که در آن اجازه‌ی بازگشت اقوام تبعیدی (از جمله یهودیان) به سرزمین خود صادر شده، گاه نخستین منشور حقوق بشر جهان خوانده می‌شود.",
"زادروز کیهان کلهر آهنگساز و نوازندهٔ برجسته ایرانی": "کیهان کلهر (زاده‌ی ۱۳۴۲ خورشیدی) نوازنده‌ی کمانچه و آهنگسازی است که با همکاری در گروه‌های بین‌المللی از جمله «سیلک رود» یویو ما، موسیقی کلاسیک ایرانی را به صحنه‌های جهانی برد و یکی از شناخته‌شده‌ترین موسیقی‌دانان ایرانی در عرصه‌ی بین‌المللی است.",
"زادروز یاور همدانی، شاعر و نویسنده و پژوهشگر ایرانی": "یاور همدانی شاعر، نویسنده و پژوهشگری بود که فعالیت‌های فرهنگی‌اش عمدتاً پیرامون همدان و ادبیات محلی این منطقه شکل گرفت.",
"زادروزخواجه عبدالله انصاری، ادیب، عارف و اندیشمند ایرانی": "خواجه عبدالله انصاری (۳۹۶-۴۸۱ هجری قمری) عارفی از هرات بود که با نثر آهنگین و موجزش در کتاب «مناجات‌نامه»، یکی از نخستین و تأثیرگذارترین آثار نثر عرفانی فارسی را پدید آورد.",
"سالروز درگذشت علی اکبر دهخدا": "علی‌اکبر دهخدا (۱۲۵۷-۱۳۳۴ خورشیدی)، روشنفکر و طنزنویس دوران مشروطه، لغت‌نامه‌ی عظیمی را گردآوری کرد که به «لغت‌نامه‌ی دهخدا» شهرت یافت و هنوز جامع‌ترین فرهنگ لغت زبان فارسی به‌شمار می‌رود؛ گردآوری این اثر دهه‌ها به طول انجامید.",
"سالروز زلزله فردوس در سال ۱۳۴۷": "زمین‌لرزه‌ی فردوس در خراسان در سال ۱۳۴۷ خورشیدی یکی از ویرانگرترین زلزله‌های سده‌ی بیستم ایران بود که خسارات جانی و مالی گسترده‌ای بر جای گذاشت.",
"سالروز شهادت رئیسعلی دلواری، سردار بزرگ میهن و فرمانده قیام جنوب علیه اشغالگران انگلیسی": "رئیسعلی دلواری (۱۲۶۱-۱۲۹۴ خورشیدی) در جریان جنگ جهانی اول، مقاومت مردمی منطقه‌ی بوشهر و تنگستان را در برابر اشغال نیروهای بریتانیایی رهبری کرد. او در یکی از درگیری‌ها کشته شد و به یکی از نمادهای مقاومت ضداستعماری جنوب ایران بدل شده است.",
"سالروز صدور فرمان مشروطیت": "مظفرالدین‌شاه قاجار در مرداد ۱۲۸۵، پس از هفته‌ها اعتراض و اعتصاب گسترده‌ی بازاریان، علما و روشنفکران، فرمان تأسیس مجلس شورای ملی و حکومت مشروطه را امضا کرد. این رویداد سرآغاز جنبش مشروطه‌ی ایران و گذار از سلطنت مطلقه به حکومت قانون بود.",
"سالروز عملیات مروارید و روز نیروی دریایی": "عملیات مروارید در آبان ۱۳۵۲، پیش از انقلاب اسلامی، توسط نیروی دریایی ارتش شاهنشاهی ایران علیه ناوگان عراق در نزدیکی جزیره‌ی خارک در خلیج فارس انجام شد و به پیروزی قاطع نیروی دریایی ایران انجامید؛ این روز از آن پس به‌عنوان روز نیروی دریایی گرامی داشته می‌شود.",
"سالروز فاجعه آتش زدن سینما رکس آبادان": "در ۲۸ مرداد ۱۳۵۷، سینما رکس آبادان در جریان نمایش یک فیلم عمداً به آتش کشیده شد و بیش از چهارصد نفر که در داخل سالن گرفتار مانده بودند (بنا بر برخی روایات، درها از بیرون بسته شده بود) جان باختند. این فاجعه یکی از مرگبارترین حوادث آتش‌سوزی عمدی تاریخ و یکی از رویدادهای تلخ و تنش‌زا در ماه‌های منتهی به انقلاب اسلامی بود؛ مسئولیت دقیق آن هنوز میان تاریخ‌نگاران محل بحث است.",
"سالروز نجات آذربایجان": "در سال ۱۳۲۵، بحران جدایی‌طلبانه‌ی «فرقه‌ی دموکرات آذربایجان» که با پشتیبانی شوروی شکل گرفته بود، پس از خروج نیروهای شوروی از ایران (تحت فشار دیپلماتیک بین‌المللی در آغاز جنگ سرد) با بازگشت کنترل دولت مرکزی بر این استان پایان یافت.",
"سالروز ورود کوروش بزرگ به بابل در سال 539 پیش از میلاد": "کوروش بزرگ در سال ۵۳۹ پیش از میلاد، عمدتاً بدون محاصره یا ویرانی گسترده، وارد بابل شد و به این ترتیب امپراتوری نو-بابلی را برانداخت. او پس از این فتح، فرمانی صادر کرد که به اقوام تبعیدی (از جمله یهودیان اسیر در بابل) اجازه‌ی بازگشت به سرزمین خود را می‌داد؛ رویدادی که در استوانه‌ی کوروش ثبت شده است.",
"سالروز وقایع 28 مرداد پس از برکناری محمد مصدق": "در ۲۸ مرداد ۱۳۳۲ (۱۹ اوت ۱۹۵۳)، کودتایی با دخالت مستقیم سازمان‌های اطلاعاتی آمریکا و بریتانیا (عملیات آژاکس)، دولت ملی و منتخب محمد مصدق را -که در پی بحران ملی‌شدن نفت با بحران روبه‌رو شده بود- سرنگون کرد و قدرت کامل را به محمدرضا شاه بازگرداند. این رویداد یکی از نقاط عطف و بحث‌برانگیزترین رخدادهای تاریخ معاصر ایران با پیامدهای سیاسی درازمدت است.",
"سفر انوشه انصاری به‌ عنوان اولین زن گردشگر فضایی به دور مدار زمین": "انوشه انصاری، مهندس و کارآفرین ایرانی‌تبار آمریکایی، در سال ۲۰۰۶ میلادی با هزینه‌ی شخصی و به‌عنوان نخستین زن گردشگر فضایی جهان، با فضاپیمای روسی سایوز به ایستگاه فضایی بین‌المللی سفر کرد. او همچنین یکی از بنیان‌گذاران جایزه‌ی ایکس آنساری بود که به توسعه‌ی فناوری‌های فضایی خصوصی کمک شایانی کرد.",
"شهادت آیت‌الله سید حسن مدرس": "سید حسن مدرس (۱۲۴۹-۱۳۱۶ خورشیدی) روحانی و نماینده‌ی مجلس بود که آشکارا با سیاست‌های استبدادی رضاشاه مخالفت می‌کرد و به همین دلیل بارها زندانی و تبعید شد. سرانجام او در تبعیدگاهش در کاشمر به دستور رضاشاه به قتل رسید (بنا بر روایات رایج، مسموم و سپس خفه شد) و به نمادی از مخالفت اصولی با استبداد سیاسی بدل شده است.",
"قتل امیرکبیر به دستور ناصرالدین شاه قاجار [1230 خورشیدی]": "میرزا تقی‌خان امیرکبیر (۱۱۸۶-۱۲۳۰ خورشیدی)، صدراعظم اصلاح‌طلب دوران آغازین سلطنت ناصرالدین‌شاه، دارالفنون -نخستین مؤسسه‌ی آموزش نوین ایران- را بنیان نهاد و اصلاحات گسترده‌ای در نظام اداری، مالی و نظامی کشور آغاز کرد. سیاست‌های او که به کاهش نفوذ درباریان و بیگانگان می‌انجامید، دشمنانی قدرتمند برایش ساخت و سرانجام به دستور شاه، در حمام فین کاشان رگ‌هایش زده شد. مرگ او را یکی از بزرگ‌ترین فرصت‌های ازدست‌رفته‌ی اصلاح در تاریخ ایران قاجار می‌دانند.",
"قتل عبدالحسین تیمورتاش، دولت‌مرد ایرانی در دوره‌های قاجار و پهلوی، در زندان قصر تهران": "عبدالحسین تیمورتاش (۱۲۶۲-۱۳۱۲ خورشیدی) وزیر دربار قدرتمند در دوران رضاشاه و از چهره‌های کلیدی مذاکرات نفتی با بریتانیا بود. او در اوج قدرت ناگهان از چشم رضاشاه افتاد، زندانی شد و در زندان قصر تهران در شرایطی مشکوک -به احتمال زیاد به دستور شاه- درگذشت.",
"لغو امتیاز تنباکو به فتوای آیت‌الله میرزا حسن شیرازی": "در واکنش به واگذاری امتیاز انحصاری تنباکوی کل کشور به یک شرکت بریتانیایی توسط ناصرالدین‌شاه، فتوایی منسوب به میرزای شیرازی، مرجع بزرگ شیعه، استعمال تنباکو را حرام اعلام کرد. این فتوا با استقبال گسترده‌ی مردم -حتی بنا بر روایاتی در اندرونی خودِ شاه- روبه‌رو شد و دولت را ناگزیر به لغو امتیاز کرد. جنبش تنباکو (۱۲۷۰ خورشیدی) یکی از نخستین و موفق‌ترین نمونه‌های مقاومت مدنی توده‌ای با ائتلاف روحانیت، بازار و افکار عمومی در تاریخ ایران است.",
"وقوع زلزله بویین زهرا و مرگ بیش از 25 هزار نفر": "زمین‌لرزه‌ی بویین‌زهرا در شهریور ۱۳۴۱ در منطقه‌ی قزوین رخ داد و بنا بر برآوردها بیش از دوازده تا بیست‌وپنج‌هزار نفر جان باختند؛ یکی از مرگبارترین زلزله‌های تاریخ معاصر ایران. این فاجعه به شکل‌گیری نخستین تلاش‌های سازمان‌یافته برای مدیریت بحران و پژوهش زلزله‌شناسی در کشور انجامید.",
"پایان سرایش شاهنامه": "فردوسی سرایش شاهنامه را در حدود سال ۴۰۰ هجری قمری، پس از نزدیک به سی سال تلاش، به پایان رساند. انگیزه‌ی او تا حد زیادی حفظ هویت فرهنگی و زبان فارسی و احیای تاریخ و اسطوره‌های پادشاهی ایران پیش از اسلام از طریق شعر بود؛ کوششی که سرنوشت زبان فارسی را برای همیشه دگرگون کرد.",
"پیروزی اسکندر مقدونی در نبرد گوگمل و شکست شاه ایران، داریوش سوم و انقراض امپراطوری بزرگ هخامنشی": "نبرد گوگمل در سال ۳۳۱ پیش از میلاد میان اسکندر مقدونی و داریوش سوم هخامنشی درگرفت. با وجود برتری عددی چشمگیر سپاه ایران، اسکندر با تاکتیک نظامی برتر پیروز شد و این شکست عملاً به فروپاشی دویست‌وچندساله‌ی شاهنشاهی هخامنشی انجامید؛ رویدادی که راه را برای تصرف پایتخت‌های ایران (از جمله سوزاندن تخت جمشید) توسط اسکندر هموار کرد.",
"کشته شدن شیخ محمد خیابانی از فعالان سیاسی در دوره انقلاب مشروطه ایران": "شیخ محمد خیابانی (۱۲۵۹-۱۲۹۹ خورشیدی) در سال ۱۲۹۹ خورشیدی جنبش «آزادیستان» را در تبریز، در اعتراض به فساد دولت مرکزی و قرارداد ۱۹۱۹ ایران و بریتانیا، رهبری کرد و برای مدتی کوتاه اداره‌ی خودمختار منطقه را در دست گرفت. این قیام سرانجام توسط نیروهای دولتی سرکوب و خود او در این جریان کشته شد.",
"کشته شدن میرزا کوچک خان جنگلی مبارز و رهبر جنبش ملی جنگل": "میرزا کوچک خان جنگلی (۱۲۵۹-۱۳۰۰ خورشیدی) رهبری نهضت جنگل را در گیلان، علیه نفوذ خارجی و دولت مرکزی، برعهده داشت و با حمایت اولیه‌ی شوروی، «جمهوری شوروی سوسیالیستی ایران» را در گیلان برپا کرد؛ هرچند بعدها با هم‌پیمانان کمونیست خود نیز اختلاف پیدا کرد. او سرانجام در حالی که از نیروهای دولتی می‌گریخت، در سرمای کوهستان‌های گیلان جان باخت.",
"کناره گیری رضا شاه از سلطنت به نفع پسرش محمدرضا پهلوی در پی اشغال ایران در جنگ جهانی دوم توسط نیروهای متفقین": "در شهریور ۱۳۲۰، پس از اشغال ایران توسط نیروهای شوروی و بریتانیا، رضاشاه تحت فشار متفقین ناگزیر به کناره‌گیری از سلطنت به نفع پسر جوانش محمدرضا پهلوی شد. او سپس به تبعید فرستاده شد (سرانجام به آفریقای جنوبی) و در سال ۱۳۲۳ در همان‌جا درگذشت؛ این رویداد به شانزده سال سلطنت اقتدارگرای نوسازی‌محور او پایان داد.",
"زمین‌لرزه‌ی رودبار و منجیل [۱۳۶۹ خورشیدی]": "در نیمه‌شبِ ۳۰ و ۳۱ خرداد ۱۳۶۹ زمین‌لرزه‌ای با بزرگای حدود ۷٫۴ شمال ایران، به‌ویژه شهرهای رودبار و منجیل در گیلان و بخش‌هایی از زنجان را لرزاند. شمار کشته‌شدگان را حدود ۴۰ هزار تن (با برآوردهایی میان ۳۵ تا ۵۰ هزار) و شمار بی‌خانمان‌ها را صدها هزار تن گفته‌اند. این رویداد از بزرگ‌ترین فاجعه‌های زمین‌لرزه‌ای ایران در سده‌ی بیستم است.",
"زمین‌لرزه‌ی طبس [۱۳۵۷ خورشیدی]": "در ۲۵ شهریور ۱۳۵۷ زمین‌لرزه‌ای با بزرگای حدود ۷٫۴ (و ۷٫۸ بر پایه‌ی مقیاس موج سطحی) ناحیه‌ی طبس در خراسان را لرزاند و شهر طبس را تقریباً به‌کلی ویران کرد. برآورد شمار کشته‌ها از حدود ۱۵ تا ۲۵ هزار تن است و بسیاری از روستاهای پیرامون نیز از میان رفتند.",
"زمین‌لرزه‌ی بم [۱۳۸۲ خورشیدی]": "بامداد ۵ دی ۱۳۸۲ زمین‌لرزه‌ای با بزرگای حدود ۶٫۶ شهر بم و پیرامونش را در استان کرمان ویران کرد. بیش از ۲۶ هزار تن جان باختند و ارگ تاریخی بم، از بزرگ‌ترین بناهای خشتیِ جهان، به‌شدت آسیب دید. «بم و چشم‌انداز فرهنگی‌اش» سال بعد در فهرست میراث جهانیِ یونسکو ثبت شد.",
"روز ایمنی در برابر زلزله و کاهش اثرات بلایای طبیعی": "۵ دی، همزمان با سالروز زمین‌لرزه‌ی بم، برای یادآوریِ آمادگی در برابر زمین‌لرزه و کاستن از پیامدهای بلاهای طبیعی نام‌گذاری شده است. ایران بر روی کمربندی لرزه‌خیز جای دارد و ساخت‌وساز استوار و آموزشِ همگانی مهم‌ترین راه کم‌کردن زیان‌های آن است.",
"روز کوروش بزرگ": "۷ آبان (برابر ۲۹ اکتبر) را به یادِ ورودِ کوروش بزرگ به بابِل در سال ۵۳۹ پیش از میلاد گرامی می‌دارند. این رویداد در نوشته‌های بابلی نیز آمده و کوروش پس از آن با سیاستی بردبارانه با مردم و آیین‌های سرزمین‌های زیر فرمانش رفتار کرد. «استوانه‌ی کوروش» که در بابل یافت شد و اکنون در موزه‌ی بریتانیا است، یادگار همین دوره است؛ ارزیابی آن به‌عنوان «نخستین منشور حقوق بشر» میان پژوهشگران گفتگو‌برانگیز است.",
"روز ملی خلیج فارس": "۱۰ اردیبهشت (۳۰ آوریل) از سال ۱۳۸۴ در گاهشمار رسمی ایران «روز ملی خلیج فارس» نام گرفت. این روز به سالروز بیرون‌راندن پرتغالی‌ها از جزیره‌ی هرمز در سال ۱۶۲۲ میلادی، در روزگار شاه‌عباس صفوی، پیوند داده می‌شود. نام «خلیج فارس» در منابع تاریخی و جغرافیایی سده‌ها به‌کار رفته است.",
"روز جزایر سه‌گانه خلیج فارس (ابوموسی، تنب بزرگ و تنب کوچک)": "۹ آذر ۱۳۵۰ (۳۰ نوامبر ۱۹۷۱)، همزمان با پایان حضور بریتانیا در خلیج فارس، نیروهای ایران در ابوموسی و دو تنب مستقر شدند. امارات متحده‌ی عربی بر این جزیره‌ها ادعا دارد و موضوع هنوز میان دو کشور محل اختلاف است.",
"عید نوروز": "نوروز، آغاز سال نوی ایرانی، جشنی چندهزارساله است که با تحویل سال در لحظه‌ی برابری بهاری آغاز می‌شود. سفره‌ی هفت‌سین، خانه‌تکانی و دید و بازدید از آیین‌های آن است. نوروز در سال ۲۰۰۹ در فهرست میراث ناملموس یونسکو ثبت شد و سازمان ملل از سال ۲۰۱۰ ۲۱ مارس را «روز جهانی نوروز» شناخته است.",
"آغاز عملیات فتح‌المبین": "عملیاتی که ایران در فروردین ۱۳۶۱ (مارس ۱۹۸۲) در جنگ ایران و عراق در منطقه‌ی دزفول و شوش در خوزستان انجام داد و در آن بخشی از سرزمین‌های اشغال‌شده را بازپس گرفت.",
"روز امید، روز شادباش نویسی": "ششم فروردین در سنت زرتشتی «خردادسال» و زادروز زرتشت دانسته می‌شود. در این روز شادباش‌نویسی و نامه‌نگاری امیدبخش رسم شمرده شده است.",
"روز جمهوری اسلامی": "پس از همه‌پرسی ۱۱ و ۱۲ فروردین ۱۳۵۸ که طبق نتایج رسمی بیش از ۹۸ درصد شرکت‌کنندگان در آن به «جمهوری اسلامی» رأی دادند، ۱۲ فروردین (۱ آوریل ۱۹۷۹) به‌عنوان آغاز این نظام اعلام شد.",
"روز طبیعت": "سیزدهم فروردین پایان جشن‌های نوروزی است. مردم به دشت و باغ می‌روند، سبزه‌ی سفره‌ی هفت‌سین را به آب می‌سپارند و سبزه گره می‌زنند؛ این آیین «سیزده‌بدر» نام دارد.",
"جشن سروشگان (سروش‌روز)": "سروش در اوستا ایزد فرمان‌برداری و نگهبان جهان است و روز هفدهم هر ماه در گاهشمار زرتشتی به نام اوست. روز سروش از فروردین «جشن سروشگان» خوانده می‌شود.",
"روز ملی فناوری هسته‌ای": "این روز به یادِ اعلام دستیابی ایران به غنی‌سازی اورانیوم در سال ۱۳۸۵ نام‌گذاری شده است. برنامه‌ی هسته‌ای ایران از آن زمان موضوع اختلاف و تحریم‌های بین‌المللی و سپس مذاکرات از جمله برجام بوده است.",
"روز هنر انقلاب اسلامی": "این روز به مناسبت درگذشت مرتضی آوینی، مستندساز و نویسنده، نام‌گذاری شده است.",
"شهادت سید مرتضی آوینی": "مرتضی آوینی، مستندساز و نویسنده، سازنده‌ی مجموعه‌ی «روایت فتح» درباره‌ی جنگ ایران و عراق بود. او در ۲۰ فروردین ۱۳۷۲ هنگام فیلم‌برداری در منطقه‌ی فکه بر اثر انفجار مین جان باخت.",
"شهادت امیر سپهبد علی صیاد شیرازی": "علی صیاد شیرازی فرمانده نیروی زمینی ارتش در جنگ ایران و عراق و از چهره‌های نامدار آن بود. او در ۲۱ فروردین ۱۳۷۸ در تهران ترور شد و سازمان مجاهدین خلق مسئولیت آن را پذیرفت.",
"تأسیس بنیاد مسکن انقلاب اسلامی": "نهادی که پس از انقلاب ۱۳۵۷ برای ساخت و بهسازی مسکن، به‌ویژه در روستاها و میان کم‌درآمدان، بنیاد نهاده شد.",
"روز ارتش جمهوری اسلامی ایران": "۲۹ فروردین روز ارتش جمهوری اسلامی است و رژه‌ی نیروهای مسلح در آن برگزار می‌شود.",
"تأسیس سپاه پاسداران انقلاب اسلامی": "سپاه پاسداران انقلاب اسلامی در فروردین و اردیبهشت ۱۳۵۸ با فرمان روح‌الله خمینی بنیان نهاده شد. این نهاد نظامی موازی ارتش است و بعدها نیروی زمینی، هوایی و دریایی و نقشی گسترده در سیاست و اقتصاد یافت.",
"سالروز اعلام انقلاب فرهنگی": "در بهار ۱۳۵۹ دانشگاه‌های ایران برای بازسازی و پاک‌سازی بسته شدند و «ستاد انقلاب فرهنگی» پدید آمد. دانشگاه‌ها حدود سه سال بسته ماندند و بسیاری از استادان و دانشجویان اخراج شدند.",
"شهادت امیر سپهبد قرنی": "ولی‌الله قرنی نخستین رئیس ستاد ارتش پس از انقلاب بود. او در ۳ اردیبهشت ۱۳۵۸ به دست گروه فرقان ترور شد.",
"شکست حمله نظامی آمریکا به ایران در طبس": "در اردیبهشت ۱۳۵۹ (آوریل ۱۹۸۰) آمریکا عملیاتی ناکام برای آزادسازی گروگان‌های سفارتش در تهران انجام داد. عملیات «پنجه‌ی عقاب» در بیابان طبس به‌دلیل خرابی بالگردها و برخورد دو هواپیما متوقف شد و هشت نظامی آمریکایی کشته شدند.",
"فاجعه‌ی انفجارِ بندر عباس [ 1404 خورشیدی]": "انفجار در بندر شهید رجایی بندرعباس در ۶ اردیبهشت ۱۴۰۴ (۲۶ آوریل ۲۰۲۵) ده‌ها کشته و بیش از هزار زخمی برجا گذاشت. گزارش‌ها از نقش محموله‌های شیمیایی در پیدایش آن حکایت دارند.",
"آغاز عملیات بیت‌المقدس": "عملیات بیت‌المقدس از ۱۰ اردیبهشت ۱۳۶۱ (آوریل ۱۹۸۲) در خوزستان انجام شد و به بازپس‌گیری خرمشهر در ۳ خرداد انجامید.",
"شهادت استاد مرتضی مطهری": "مرتضی مطهری روحانی و فیلسوف شیعه و از نظریه‌پردازان انقلاب بود. او در ۱۲ اردیبهشت ۱۳۵۸ در تهران به دست گروه فرقان ترور شد. روز معلم هم به همین مناسبت نام‌گذاری شده است.",
"روز جهانی زن در ریاضیات (زادروز مریم میرزاخانی)": "مریم میرزاخانی (۱۳۵۶–۱۳۹۶)، ریاضی‌دان ایرانی، در سال ۲۰۱۴ نخستین زنی بود که مدال فیلدز را گرفت. او در ۲۲ اردیبهشت (۱۲ مه) زاده شد و این روز به یاد او «روز جهانی زن در ریاضیات» است.",
"فروریختن ساختمان متروپل در آبادان": "ساختمان تجاری متروپل در آبادان در ۲ خرداد ۱۴۰۱ (۲۳ مه ۲۰۲۲) فرو ریخت و دست‌کم ۴۰ تن جان باختند. بی‌توجهی به ایمنی ساخت‌وساز در پی‌جویی‌ها برجسته شد.",
"فتح خرمشهر در عملیات بیت المقدس و روز مقاومت، ایثار و پیروزی": "خرمشهر از آبان ۱۳۵۹ در اشغال نیروهای عراق بود و ایران آن را در ۳ خرداد ۱۳۶۱ (۲۴ مه ۱۹۸۲) در عملیات بیت‌المقدس بازپس گرفت.",
"روز دزفول، روز مقاومت و پایداری": "دزفول در جنگ ایران و عراق بارها هدف حمله‌ی هوایی و موشکی بود. این روز یادآور ایستادگی مردم این شهر است.",
"افتتاح اولین دوره مجلس شورای اسلامی": "نخستین دوره‌ی مجلس شورای اسلامی در ۷ خرداد ۱۳۵۹ (۲۸ مه ۱۹۸۰) گشایش یافت.",
"رحلت حضرت امام خمینی": "روح‌الله خمینی، بنیان‌گذار جمهوری اسلامی و نخستین رهبر آن، در ۱۴ خرداد ۱۳۶۸ (۴ ژوئن ۱۹۸۹) درگذشت. خاکسپاری او با شرکت میلیون‌ها نفر برگزار شد.",
"انتخاب آیت‌الله خامنه‌ای به رهبری": "پس از درگذشت خمینی، مجلس خبرگان رهبری در ۱۴ خرداد ۱۳۶۸ علی خامنه‌ای را که رئیس‌جمهور بود به رهبری برگزید. قانون اساسی چند ماه بعد بازنگری شد.",
"قیام 15 خرداد": "در ۱۵ خرداد ۱۳۴۲ (۵ ژوئن ۱۹۶۳)، پس از بازداشت خمینی به‌دلیل سخنرانی علیه «انقلاب سفید» شاه، در تهران و چند شهر دیگر اعتراض‌هایی برپا شد که با سرکوب همراه بود. شمار کشته‌ها در برآوردها از ده‌ها تا هزاران تن متفاوت است.",
"شهادت آیت‌الله سعیدی": "رضا سعیدی روحانی مخالف حکومت پهلوی بود که در خرداد ۱۳۴۹ در بازداشت درگذشت. مخالفان مرگ او را شکنجه‌ی ساواک می‌دانند.",
"روز شهدای اقتدار و اتحاد ملی": "در ۲۳ خرداد ۱۴۰۴ (۱۳ ژوئن ۲۰۲۵) اسرائیل با حمله‌ای گسترده به ایران جنگی ۱۲روزه را آغاز کرد که در آن شماری از فرماندهان نظامی و دانشمندان هسته‌ای ایرانی کشته شدند. آمریکا نیز در ۲۲ ژوئن به چند پایگاه هسته‌ای ایران حمله کرد و جنگ با آتش‌بس در ۲۴ ژوئن پایان یافت.",
"شهادت بخارایی، امانی، صفار هرندی و نیک‌نژاد": "محمد بخارایی و چند عضو دیگر هیئت‌های مؤتلفه‌ی اسلامی به اتهام ترور حسنعلی منصور، نخست‌وزیر، در ۱۳۴۳ بازداشت شدند و در ۱۳۴۴ اعدام شدند.",
"تشکیل جهاد سازندگی": "جهاد سازندگی نهادی برای عمران روستایی بود که در ۱۳۵۸ با فرمان خمینی تشکیل شد و در ۱۳۹۱ با وزارت کشاورزی ادغام شد.",
"درگذشت دکتر علی شریعتی": "علی شریعتی، جامعه‌شناس و اندیشمند دینی، در ۲۹ خرداد ۱۳۵۶ (۱۹ ژوئن ۱۹۷۷) در انگلستان درگذشت. علت مرگ او، که حمله‌ی قلبی اعلام شد، اختلاف‌برانگیز است. آثار او بر نسل انقلاب ۱۳۵۷ اثر بسیار گذاشت.",
"شهادت زائران حرم رضوی": "در روز عاشورا ۱۳۷۳ (۲۰ ژوئن ۱۹۹۴) بمب‌گذاری در حرم امام رضا در مشهد دست‌کم ۲۵ کشته و ده‌ها زخمی برجا گذاشت.",
"شهادت دکتر مصطفی چمران": "مصطفی چمران فیزیک‌دان و نخستین وزیر دفاع پس از انقلاب بود. او در ۳۱ خرداد ۱۳۶۰ در جنگ ایران و عراق در منطقه‌ی دهلاویه کشته شد.",
"درگذشت ابن سینا پزشک و فیلسوف ایرانی": "ابن سینا (حدود ۹۸۰–۱۰۳۷ میلادی) پزشک و فیلسوف ایرانی، زاده‌ی نزدیکی بخارا بود. «قانون در طب» و «شفا» از مهم‌ترین آثار او است و در همدان درگذشت.",
"انفجار دفتر حزب جمهوری اسلامی و شهادت دکتر بهشتی و 72 نفر از اعضای حزب": "در ۷ تیر ۱۳۶۰ (۲۸ ژوئن ۱۹۸۱) بمبی در دفتر حزب جمهوری اسلامی در تهران منفجر شد و محمد بهشتی، رئیس دیوان عالی کشور، و حدود ۷۰ تن دیگر کشته شدند. سازمان مجاهدین خلق متهم اصلی شناخته شد.",
"روز قوه قضاییه": "این روز به یاد محمد بهشتی، نخستین رئیس دیوان عالی کشور پس از انقلاب، که در ۷ تیر ۱۳۶۰ کشته شد، نام‌گذاری شده است.",
"بمباران شیمیایی شهر سردشت": "در ۷ تیر ۱۳۶۶ (۲۸ ژوئن ۱۹۸۷) هواپیماهای عراق سردشت در آذربایجان غربی را با سلاح شیمیایی بمباران کردند. در این حمله حدود ۱۱۰ تن کشته و هزاران تن زخمی شدند.",
"روز مبارزه با سلاح های شیمیایی و میکروبی": "این روز پس از بمباران شیمیایی سردشت (۷ تیر ۱۳۶۶) نام‌گذاری شده است.",
"شلیک به پرواز 655 ایران ایر توسط ناو وینسنس [ 1367 خورشیدی ]": "ناو آمریکایی وینسنس در ۱۲ تیر ۱۳۶۷ (۳ ژوئیه ۱۹۸۸) بر فراز خلیج فارس هواپیمای ایرباس ایران ایر را هدف قرار داد و هر ۲۹۰ سرنشین کشته شدند. آمریکا آن را اشتباه خواند و در ۱۹۹۶ در دیوان لاهه با پرداخت غرامت موافقت کرد.",
"روز افشای حقوق بشر آمریکایی": "این روز را ایران به مناسبت شلیک ناو آمریکایی به پرواز ۶۵۵ (۱۲ تیر ۱۳۶۷) نام‌گذاری کرده است.",
"کشف توطئه آمریکایی در پایگاه هوایی شهید نوژه": "بر پایه‌ی روایت رسمی، در تیر ۱۳۵۹ کودتایی که افسران ارتش در پایگاه نوژه‌ی همدان و جاهای دیگر برنامه‌ریزی کرده بودند کشف شد. شماری از دستگیرشدگان اعدام شدند.",
"گشایش نخستین مجلس خبرگان رهبری": "نخستین دوره‌ی مجلس خبرگان رهبری، نهادی که رهبر را برمی‌گزیند و بر او نظارت می‌کند، در ۱۳۶۲ آغاز به کار کرد.",
"تأسیس نهاد شورای نگهبان": "شورای نگهبان، نهادی دوازده‌نفره، مصوبات مجلس را با شرع و قانون اساسی می‌سنجد و بر صلاحیت نامزدهای انتخابات نظارت دارد. این نهاد در ۱۳۵۹ شکل گرفت.",
"اعلام پذیرش قطعنامه 598 شورای امنیت از سوی ایران [ 1367 خورشیدی ]": "ایران در ۲۷ تیر ۱۳۶۷ (۱۸ ژوئیه ۱۹۸۸) قطعنامه‌ی ۵۹۸ شورای امنیت را پذیرفت. آتش‌بس در ۲۹ مرداد برقرار شد و جنگ هشت‌ساله‌ی ایران و عراق پایان یافت.",
"بزرگداشت آیت‌الله کاشانی": "ابوالقاسم کاشانی روحانی سیاسی بود که در جنبش ملی شدن نفت با محمد مصدق همراه بود و بعدها از او جدا شد.",
"سالروز عملیات افتخارآفرین مرصاد": "پس از پذیرش آتش‌بس در ۱۳۶۷ نیروهای سازمان مجاهدین خلق با پشتیبانی عراق از مرز غربی وارد ایران شدند. نیروهای ایران آن‌ها را در عملیاتی که «مرصاد» نام گرفت عقب راندند.",
"تشکیل جهاد دانشگاهی": "جهاد دانشگاهی پس از انقلاب فرهنگی در ۱۳۵۹ برای پیوند دانشگاه با صنعت و جامعه بنیان نهاده شد.",
"روز خبرنگار": "روز خبرنگار به یاد محمود صارمی، خبرنگار خبرگزاری جمهوری اسلامی، نام‌گذاری شده است. او در ۱۷ مرداد ۱۳۷۷ (۸ اوت ۱۹۹۸) در مزارشریف در افغانستان همراه چند دیپلمات ایرانی به دست طالبان کشته شد.",
"سالروز شهادت محمود صارمی": "محمود صارمی، خبرنگار خبرگزاری جمهوری اسلامی، در ۱۷ مرداد ۱۳۷۷ (۸ اوت ۱۹۹۸) در مزارشریف در افغانستان همراه چند دیپلمات ایرانی به دست طالبان کشته شد.",
"بزرگداشت شهدای مدافع حرم": "ایرانیانی که در جنگ سوریه و عراق با پشتیبانی ایران علیه گروه‌هایی مانند داعش جنگیدند و کشته شدند. این روز با کشته‌شدن محسن حججی به دست داعش در ۱۳۹۶ پیوند خورده است.",
"سالروز ورود آزادگانِ سرافراز به وطن": "پس از پایان جنگ، بازگشت اسیران جنگی ایران از عراق از ۲۶ مرداد ۱۳۶۹ (۱۷ اوت ۱۹۹۰) آغاز شد. بسیاری از آنان بیش از ده سال در اسارت بودند.",
"گشایش مجلس خبرگان": "نخستین مجلس خبرگان برای نوشتن قانون اساسی جمهوری اسلامی در مرداد ۱۳۵۸ گشایش یافت.",
"انفجار در دفتر نخست‌وزیری جمهوری اسلامی ایران، روز مبارزه با تروریسم": "در ۸ شهریور ۱۳۶۰ (۳۰ اوت ۱۹۸۱) بمبی در دفتر نخست‌وزیری در تهران محمدعلی رجایی، رئیس‌جمهور، و محمدجواد باهنر، نخست‌وزیر، را کشت. سازمان مجاهدین خلق متهم اصلی شناخته شد و این روز «روز مبارزه با تروریسم» نام گرفت.",
"شهادت شهیدان رجایی و باهنر": "در ۸ شهریور ۱۳۶۰ (۳۰ اوت ۱۹۸۱) بمبی در دفتر نخست‌وزیری در تهران محمدعلی رجایی، رئیس‌جمهور، و محمدجواد باهنر، نخست‌وزیر، را کشت. سازمان مجاهدین خلق متهم اصلی شناخته شد.",
"قیام 17 شهریور": "در ۱۷ شهریور ۱۳۵۷ (۸ سپتامبر ۱۹۷۸) پس از اعلام حکومت نظامی، نیروهای دولتی در میدان ژاله‌ی تهران به معترضان شلیک کردند. شمار کشته‌ها را در برآوردها از ده‌ها تا هزاران تن گفته‌اند. این روز «جمعه‌ی سیاه» نیز خوانده می‌شود.",
"درگذشت آیت الله سید محمود طالقانی": "محمود طالقانی روحانی و از رهبران انقلاب ۱۳۵۷ بود و در مجلس خبرگان قانون اساسی نقش داشت. او در ۱۹ شهریور ۱۳۵۸ درگذشت.",
"درگذشت محمدعلی جناح بنیانگذار کشور پاکستان": "محمدعلی جناح بنیان‌گذار پاکستان و نخستین فرماندار کل آن بود. او در ۱۱ سپتامبر ۱۹۴۸ درگذشت.",
"شهادت آیت‌الله مدنی": "اسدالله مدنی امام جمعه‌ی تبریز بود که در ۲۰ شهریور ۱۳۶۰ در حمله‌ای انتحاری کشته شد.",
"اعدام صادق قطب‌زاده، وزیر سابق امور خارجه جمهوری اسلامی ایران": "صادق قطب‌زاده، وزیر امور خارجه‌ی پیشین و از نزدیکان خمینی، به اتهام دست‌داشتن در توطئه‌ی براندازی در ۲۴ شهریور ۱۳۶۱ اعدام شد.",
"لغو عهدنامه ۱۹۷۵ الجزایر توسط صدام حسین": "صدام حسین در ۲۶ شهریور ۱۳۵۹ (۱۷ سپتامبر ۱۹۸۰) قرارداد الجزایر (۱۹۷۵) درباره‌ی مرز اروندرود را لغو کرد. پنج روز بعد عراق به ایران حمله کرد.",
"سالروز ترور میکونوس در شهر برلین": "در ۲۶ شهریور ۱۳۷۱ (۱۷ سپتامبر ۱۹۹۲) در رستوران میکونوس در برلین چند رهبر کرد ایرانی، از جمله صادق شرفکندی، کشته شدند. دادگاه آلمان در ۱۹۹۷ مقام‌های ایرانی را مسئول شناخت و اتحادیه‌ی اروپا سفیرانش را از تهران فراخواند.",
"بزرگداشت استاد شهریار": "محمدحسین شهریار (۱۲۸۵–۱۳۶۷)، شاعر آذربایجانی‌تبار، به پارسی و ترکی شعر می‌سرود. شعر ترکی «حیدربابایه سلام» از مشهورترین آثار او است. او در ۲۷ شهریور ۱۳۶۷ درگذشت و این روز «روز شعر و ادب فارسی» نام گرفته است.",
"روز شعر و ادب فارسی": "این روز به یاد محمدحسین شهریار (درگذشته‌ی ۲۷ شهریور ۱۳۶۷)، شاعر آذربایجانی‌تبار، «روز شعر و ادب فارسی» نام‌گذاری شده است.",
"آغاز جنگ تحمیلی": "در ۳۱ شهریور ۱۳۵۹ (۲۲ سپتامبر ۱۹۸۰) عراق به ایران حمله کرد. جنگ ایران و عراق تا ۱۳۶۷ ادامه یافت و برآوردها از شمار کشته‌های دو سو از چند صد هزار تا نزدیک یک میلیون تن متفاوت است.",
"آغاز هفته دفاع مقدس": "از ۳۱ شهریور، سالروز آغاز جنگ ایران و عراق در ۱۳۵۹، یک هفته به یادبود جنگ هشت‌ساله اختصاص دارد.",
"انحلال حزب رستاخیز": "حزب رستاخیز را شاه در ۱۳۵۳ به‌عنوان تنها حزب مجاز بنیان نهاد. در پی اعتراض‌های ۱۳۵۷ در مهر همان سال منحل شد.",
"شکست حصر آبادان": "آبادان از مهر ۱۳۵۹ در محاصره‌ی نیروهای عراق بود. ایران در عملیات ثامن‌الائمه در ۵ مهر ۱۳۶۰ (۲۷ سپتامبر ۱۹۸۱) محاصره را شکست.",
"اعدام سید مهدی هاشمی به جرم توطئه علیه نظام و بانی فاش ساختن رسوایی ایران-کنترا": "مهدی هاشمی از نزدیکان حسینعلی منتظری بود و در ۱۳۶۶ اعدام شد. او پیش‌تر در ماجرای افشای سفر مک‌فارلین به تهران (رسوایی ایران-کنترا) نامش مطرح شده بود. اتهام‌ها و انگیزه‌ی اعدام او اختلاف‌برانگیز است.",
"سقوط هواپیمای حامل جمعی از فرماندهان جنگ (کلاهدوز، نامجو، فلاحی، فکوری، جهان آرا) در سال 1360": "در ۷ مهر ۱۳۶۰ (۲۹ سپتامبر ۱۹۸۱) هواپیمای حامل شماری از فرماندهان ارشد جنگ، از جمله جهان‌آرا و کلاهدوز، سقوط کرد و همه‌ی سرنشینان جان باختند. این روز به یادبود فرماندهان جنگ نام‌گذاری شده است.",
"بزرگداشت فرماندهان شهید دفاع مقدس": "در ۷ مهر ۱۳۶۰ (۲۹ سپتامبر ۱۹۸۱) هواپیمای حامل شماری از فرماندهان ارشد جنگ، از جمله جهان‌آرا و کلاهدوز، سقوط کرد و همه‌ی سرنشینان جان باختند.",
"هجرت امام خمینی از عراق به پاریس": "خمینی که از ۱۳۴۴ در نجف بود، در مهر ۱۳۵۷ (اکتبر ۱۹۷۸) به فشار دولت عراق ناچار به ترک آن کشور شد. کویت او را نپذیرفت و او به نوفل‌لوشاتو در نزدیکی پاریس رفت.",
"شهادت آیت‌الله اشرفی اصفهانی": "آیت‌الله اشرفی اصفهانی امام جمعه‌ی کرمانشاه بود و در ۱۳۶۰ در حمله‌ای انتحاری کشته شد.",
"اعدام سرهنگ عزت‌الله سیامک به همراه 9 تن دیگر به عنوان اولین گروه از افسران حزب توده بعد از ماجرای 28 مرداد": "پس از کودتای ۲۸ مرداد ۱۳۳۲، شماری از افسران وابسته به حزب توده در ارتش شناسایی و محاکمه شدند. گروهی از آنان از جمله عزت‌الله سیامک در ۱۳۳۳ اعدام شدند.",
"شهادت آیت‌الله سید مصطفی خمینی": "مصطفی خمینی، فرزند روح‌الله خمینی، در ۱ آبان ۱۳۵۶ در نجف ناگهان درگذشت. مخالفان مرگ او را به ساواک نسبت دادند و مراسم یادبود او اعتراض‌های ۱۳۵۶ را دامن زد.",
"اعتراض امام خمینی علیه پذیرش کاپیتولاسیون": "خمینی در ۴ آبان ۱۳۴۳ (۲۶ اکتبر ۱۹۶۴) به لایحه‌ای که مستشاران نظامی آمریکایی را از مصونیت قضایی برخوردار می‌کرد، اعتراض کرد. کمی بعد تبعید شد.",
"شهادت محمدحسین فهمیده (بسیجی ۱۳ ساله)": "محمدحسین فهمیده، نوجوان ۱۳ ساله‌ی بسیجی، در ۸ آبان ۱۳۵۹ (۳۰ اکتبر ۱۹۸۰) در خرمشهر هنگام حمله به یک تانک عراقی کشته شد. این روز «روز نوجوان» نیز نام دارد.",
"شهادت آیت‌الله قاضی طباطبایی": "محمدعلی قاضی طباطبایی از رهبران تبریز بود و در ۱۰ آبان ۱۳۵۸ در تبریز به دست گروه فرقان ترور شد.",
"تسخیر سفارت آمریکا": "در ۱۳ آبان ۱۳۵۸ (۴ نوامبر ۱۹۷۹) دانشجویان سفارت آمریکا در تهران را اشغال کردند و ۵۲ آمریکایی را ۴۴۴ روز گروگان گرفتند. گروگان‌ها پس از «بیانیه‌ی الجزایر» در ۲۰ ژانویه ۱۹۸۱ آزاد شدند.",
"روز ملی مبارزه با استکبار جهانی": "این روز به مناسبت ۱۳ آبان ۱۳۵۸ (اشغال سفارت آمریکا)، ۱۳ آبان ۱۳۴۳ (تبعید خمینی) و ۱۳ آبان ۱۳۵۷ (کشتار دانش‌آموزان در تهران) نام‌گذاری شده است.",
"تبعید امام خمینی از ایران به ترکیه": "خمینی در ۱۳ آبان ۱۳۴۳ (۴ نوامبر ۱۹۶۴) به ترکیه و سپس عراق تبعید شد. او تا ۱۳۵۷ در نجف بود.",
"سالروز آزادسازی سوسنگرد": "سوسنگرد در آبان ۱۳۵۹ در جنگ ایران و عراق به‌دست ایران بازپس گرفته شد.",
"روز بسیج مستضعفان": "بسیج، نیروی مردمی داوطلب، در ۵ آذر ۱۳۵۸ با فرمان خمینی بنیان نهاده شد و بعدها زیر نظر سپاه پاسداران درآمد.",
"رسمی شدن قانون اساسی جمهوری اسلامی ایران": "قانون اساسی جمهوری اسلامی با همه‌پرسی ۱۱ و ۱۲ آذر ۱۳۵۸ تصویب شد. این قانون در ۱۳۶۸ بازنگری شد.",
"معرفی عراق به‌عنوان آغازگر جنگ از سوی سازمان ملل": "دبیرکل سازمان ملل در ۱۸ آذر ۱۳۷۰ (۹ دسامبر ۱۹۹۱) در گزارشی عراق را آغازگر جنگ با ایران خواند.",
"تشکیل شورای عالی انقلاب فرهنگی": "این شورا در ۱۳۶۳ برای سیاست‌گذاری فرهنگی و آموزشی بنیان نهاده شد و رهبر ریاست آن را بر عهده دارد.",
"شهادت آیت‌الله دستغیب": "عبدالحسین دستغیب امام جمعه‌ی شیراز بود و در ۲۰ آذر ۱۳۶۰ در حمله‌ای انتحاری کشته شد.",
"شهادت آیت‌الله دکتر محمد مفتح": "محمد مفتح روحانی و از بنیان‌گذاران «وحدت حوزه و دانشگاه» بود. او در ۲۷ آذر ۱۳۵۸ در تهران ترور شد.",
"روز میلاد خورشید": "پس از بلندترین شب سال (یلدا) از روز نخست دی روزها دوباره بلندتر می‌شوند. در سنت‌های ایرانی این را «زایش دوباره‌ی خورشید» می‌خوانند.",
"جشن خرم‌روز، نخستین جشن دی‌گان": "نخستین روز دی‌ماه «خرم‌روز» (هرمزد) است. دی در سنت زرتشتی نام آفریدگار است و چهار روز این ماه جشن دی‌گان خوانده می‌شود.",
"سالروز شهادت آشو زرتشت، اَبَراِنسان بزرگ تاریخ": "زرتشت پیامبر ایرانی و آورنده‌ی آیین زرتشتی است. سنت زرتشتی درگذشت او را حدود ۵۵۱ پیش از میلاد می‌داند، اما زمان زندگی او میان پژوهشگران بسیار اختلاف‌برانگیز است.",
"تشکیل نهضت سوادآموزی": "نهضت سوادآموزی در ۱۳۵۸ برای کاستن از بی‌سوادی بنیان نهاده شد.",
"روز بصیرت": "پس از اعتراض به نتیجه‌ی انتخابات ریاست‌جمهوری ۱۳۸۸، در ۹ دی ۱۳۸۸ راهپیمایی‌های هواداران حکومت برگزار شد. این روز بعدها «روز بصیرت» نام گرفت.",
"شهادت سردار حاج قاسم سلیمانی [1398 خورشیدی]": "قاسم سلیمانی فرمانده نیروی قدس سپاه بود. او در ۱۳ دی ۱۳۹۸ (۳ ژانویه ۲۰۲۰) در حمله‌ی پهپادی آمریکا نزدیک فرودگاه بغداد کشته شد. ایران پنج روز بعد به پایگاه عین‌الاسد در عراق موشک زد.",
"روز جهانی مقاومت": "این روز به مناسبت کشته‌شدن قاسم سلیمانی در ۱۳ دی ۱۳۹۸ نام‌گذاری شده است.",
"غرق شدن کشتی سانچی [1396 خورشیدی]": "نفتکش ایرانی سانچی در ۱۶ دی ۱۳۹۶ (۶ ژانویه ۲۰۱۸) در دریای چین شرقی با یک کشتی باری برخورد کرد و آتش گرفت. هر ۳۲ خدمه‌اش جان باختند.",
"حادثه کشته شدن 56 تن از تشیع کنندگان در کرمان": "در مراسم خاکسپاری قاسم سلیمانی در کرمان در ۱۷ دی ۱۳۹۸ (۷ ژانویه ۲۰۲۰) ازدحام جمعیت ۵۶ کشته و بیش از دویست زخمی برجا گذاشت.",
"شلیک به پرواز 752 هواپیمایی اوکراین [1398 خورشیدی]": "پدافند هوایی سپاه در ۱۸ دی ۱۳۹۸ (۸ ژانویه ۲۰۲۰) پس از برخاستن از تهران هواپیمای مسافربری اوکراینی را زد و هر ۱۷۶ سرنشین کشته شدند. ایران پس از سه روز انکار، آن را به «خطای انسانی» نسبت داد.",
"درگذشت اکبر هاشمی رفسنجانی [1395 خورشیدی]": "اکبر هاشمی رفسنجانی رئیس‌جمهور (۱۳۶۸–۱۳۷۶) و رئیس مجمع تشخیص مصلحت نظام بود. او در ۱۹ دی ۱۳۹۵ (۸ ژانویه ۲۰۱۷) درگذشت.",
"قیام خونین مردم قم": "در ۱۹ دی ۱۳۵۶ (۹ ژانویه ۱۹۷۸) پس از چاپ مقاله‌ای توهین‌آمیز به خمینی در روزنامه‌ی اطلاعات، در قم اعتراض شد و نیروهای امنیتی شماری از معترضان را کشتند. این رخداد آغاز چرخه‌ی اعتراض‌های چهلم در ۱۳۵۷ شد.",
"تشکیل شورای انقلاب": "شورای انقلاب در دی ۱۳۵۷ به فرمان خمینی برای رهبری دوران انتقال تشکیل شد و تا گشایش مجلس در ۱۳۵۹ کار کرد.",
"اجرای توافق نامه‌ی برجام": "برجام (توافق هسته‌ای) در ۲۷ دی ۱۳۹۴ (۱۷ ژانویه ۲۰۱۶) پس از تأیید آژانس بین‌المللی انرژی اتمی اجرا شد و بخشی از تحریم‌ها برداشته شد. آمریکا در ۲۰۱۸ از آن بیرون آمد.",
"شهادت نواب صفوی، طهماسبی، برادران واحدی و ذوالقدر": "نواب صفوی بنیان‌گذار فدائیان اسلام بود. او همراه چند تن دیگر پس از سوءقصد به حسین علاء، نخست‌وزیر، در ۲۷ دی ۱۳۳۴ (۱۸ ژانویه ۱۹۵۶) اعدام شد.",
"روز غزه": "این روز به یاد جنگ ۲۲روزه‌ی غزه (دسامبر ۲۰۰۸ تا ژانویه ۲۰۰۹) نام‌گذاری شده است.",
"آتش‌سوزی و فروریختن ساختمان پلاسکو [1395 خورشیدی]": "ساختمان پلاسکو در تهران در ۳۰ دی ۱۳۹۵ (۱۹ ژانویه ۲۰۱۷) پس از آتش‌سوزی فرو ریخت و دست‌کم ۲۰ تن، بیشترشان آتش‌نشان، کشته شدند.",
"بازگشت امام خمینی (ره) به ایران": "خمینی در ۱۲ بهمن ۱۳۵۷ (۱ فوریه ۱۹۷۹) پس از ۱۴ سال دوری از ایران با پرواز از پاریس به تهران بازگشت. میلیون‌ها نفر به استقبال او آمدند. «دهه‌ی فجر» از این روز تا ۲۲ بهمن است.",
"آغاز دهه فجر انقلاب اسلامی": "دهه‌ی فجر از ۱۲ تا ۲۲ بهمن، یعنی از بازگشت خمینی به ایران تا پیروزی انقلاب ۱۳۵۷ است.",
"شکسته شدن حکومت نظامی به فرمان امام خمینی": "در ۲۱ بهمن ۱۳۵۷ (۱۰ فوریه ۱۹۷۹) مردم از فرمان حکومت نظامی دولت بختیار سرپیچی کردند. نبرد میان نیروی هوایی و گارد شاهنشاهی در تهران در آن روزها رخ داد.",
"پیروزی انقلاب اسلامی": "در ۲۲ بهمن ۱۳۵۷ (۱۱ فوریه ۱۹۷۹) دولت شاپور بختیار و حکومت پهلوی فروپاشید. پس از همه‌پرسی ۱۲ فروردین ۱۳۵۸ جمهوری اسلامی بنیان گذاشته شد.",
"فاجعه انفجار قطار نیشابور [1382 خورشیدی]": "در ۲۹ بهمن ۱۳۸۲ (۱۸ فوریه ۲۰۰۴) قطار حامل گوگرد، سوخت و کود شیمیایی نزدیک نیشابور منفجر شد و بیش از ۲۰۰ تن کشته شدند.",
"قیام مردم تبریز": "در ۲۹ بهمن ۱۳۵۶ (۱۸ فوریه ۱۹۷۸) در چهلم کشته‌شدگان قم، در تبریز اعتراض‌هایی روی داد که با درگیری و کشته شدن شماری همراه بود.",
"روز بزرگداشت زمین و بانوان": "اسفندگان یا سپندارمذگان جشن ایرانی زمین، مهر و بانوان است. سپندارمذ (سپنتا آرمیتی) در اوستا ایزدبانوی زمین و فروتنی است و این روز در ایران امروز با ارج‌نهادن به مادران و همسران همراه شده است.",
"روز درختکاری": "درختکاری در ۱۵ اسفند، آغاز «هفته‌ی منابع طبیعی»، رسمی رایج در ایران است.",
"بمباران شیمیایی حلبچه به دست ارتش بعث عراق": "در ۲۵ اسفند ۱۳۶۶ (۱۶ مارس ۱۹۸۸) هواپیماهای عراق شهر کردنشین حلبچه را با سلاح شیمیایی بمباران کردند. شمار کشته‌ها را از ۳۲۰۰ تا ۵۰۰۰ تن، بیشتر غیرنظامی، برآورد کرده‌اند. چند کشور این رخداد را نسل‌کشی شناخته‌اند.",
};
